                ),
                Span::raw("   "),
                Span::styled("Routing Efficiency: ", Style::default().fg(Color::DarkGray)),
                Span::styled(
                    format!("{:.0}%", self.routing_efficiency()),
                    Style::default().fg(Color::Green),
