            Line::from(vec![
                Span::styled("Complexity Distribution: ", Style::default().fg(Color::DarkGray)),
                Span::styled(
                    format!("{} simple", self.data.complexity_distribution.0),
                    Style::default().fg(Color::Green),
                ),
                Span::raw(" | "),
                Span::styled(
                    format!("{} moderate", self.data.complexity_distribution.1),
