    pub fn take_pending_bell(&mut self) -> bool {
        self.alert_notifier.take_pending_bell()
    }

    /// Check if visual flash is currently active.
    pub fn is_flashing(&self) -> bool {
        self.alert_notifier.is_flashing()
    }
