/// Available views in the FORGE dashboard.
///
/// Each view represents a distinct screen with its own content and interactions.
/// Views can be switched using hotkeys or the Tab key to cycle.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum View {
    /// Overview/dashboard showing summary of all components
    #[default]
    Overview,
    /// Worker pool management and status
    Workers,
    /// Task queue and bead management
    Tasks,
    /// Cost analytics and optimization
    Costs,
    /// Performance metrics and statistics
    Metrics,
    /// FORGE internal performance (event loop, render time, memory)
    Perf,
    /// Activity log viewer
    Logs,
    /// Subscription tracking and utilization
    Subscriptions,
    /// Worker health alerts and notifications
    Alerts,
    /// Model routing analytics and complexity scoring
    Routing,
    /// Conversational chat interface (activated with `:`)
    Chat,
}

impl View {
    /// Returns the hotkey character for this view.
    pub fn hotkey(&self) -> char {
        match self {
            View::Overview => 'o',
            View::Workers => 'w',
            View::Tasks => 't',
            View::Costs => 'c',
            View::Metrics => 'm',
            View::Perf => 'p',
            View::Logs => 'l',
            View::Subscriptions => 'u',
            View::Alerts => 'a',
            View::Chat => ':',
        }
    }

    /// Returns the display title for this view.
    pub fn title(&self) -> &'static str {
        match self {
            View::Overview => "Overview",
            View::Workers => "Workers",
            View::Tasks => "Tasks",
            View::Costs => "Costs",
            View::Metrics => "Metrics",
            View::Perf => "Perf",
            View::Logs => "Logs",
            View::Subscriptions => "Subscriptions",
            View::Alerts => "Alerts",
            View::Chat => "Chat",
        }
    }

    /// Returns the hotkey hint for status bar display.
    pub fn hotkey_hint(&self) -> String {
        format!("[{}] {}", self.hotkey(), self.title())
    }

    /// All views in display order (for Tab cycling).
    pub const ALL: [View; 10] = [
        View::Overview,
        View::Workers,
        View::Tasks,
        View::Costs,
        View::Metrics,
        View::Perf,
        View::Logs,
        View::Subscriptions,
        View::Alerts,
        View::Chat,
    ];

    /// Returns the next view in the cycle (for Tab navigation).
    pub fn next(&self) -> View {
        let idx = Self::ALL.iter().position(|v| v == self).unwrap_or(0);
        Self::ALL[(idx + 1) % Self::ALL.len()]
    }

    /// Returns the previous view in the cycle (for Shift+Tab navigation).
    pub fn prev(&self) -> View {
        let idx = Self::ALL.iter().position(|v| v == self).unwrap_or(0);
        if idx == 0 {
            Self::ALL[Self::ALL.len() - 1]
        } else {
            Self::ALL[idx - 1]
        }
    }

    /// Try to parse a view from a hotkey character.
    pub fn from_hotkey(key: char) -> Option<View> {
        match key.to_ascii_lowercase() {
            'o' => Some(View::Overview),
            'w' => Some(View::Workers),
            't' => Some(View::Tasks),
            'c' => Some(View::Costs),
            'm' => Some(View::Metrics),
            'p' => Some(View::Perf),
            'l' => Some(View::Logs),
            'u' => Some(View::Subscriptions),
            'a' => Some(View::Alerts),
            ':' => Some(View::Chat),
            _ => None,
        }
    }
}

impl fmt::Display for View {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
