    #[default]
    None,
    /// Worker pool panel
    WorkerPool,
    /// Subscription/usage panel
    Subscriptions,
    /// Task queue panel
    TaskQueue,
    /// Activity log panel
    ActivityLog,
    /// Cost breakdown panel
    CostBreakdown,
    /// Metrics charts panel
    MetricsCharts,
    /// Perf metrics panel
    PerfCharts,
    /// Chat input panel
    ChatInput,
    /// Alert list panel
    AlertList,
}

impl FocusPanel {
