    /// Add an activity entry manually.
    pub fn add_activity(
        &mut self,
        event_type: ActivityEventType,
        source: Option<&str>,
        message: impl Into<String>,
    ) {
        let mut entry = ActivityEntry::new(event_type, message);
        if let Some(s) = source {
