    #[test]
    fn test_e2e_log_streaming() {
        let temp_dir = TempDir::new().unwrap();
        let log_dir = temp_dir.path().join("logs");
        fs::create_dir_all(&log_dir).unwrap();

        // Create a log file with initial entries
        let log_path = create_test_log_file(
