        assert!(buffer.area.height == 25);
        assert!(buffer_contains(&buffer, "FORGE"));
    }

    /// Test narrow mode at 119x40 (width limit boundary)
    /// 119 cols is just under the 120 wide threshold
    #[test]
    fn test_boundary_119x40_narrow_width_limit() {
