                if let StatusEvent::WorkerUpdated { ref status, .. } = event {
                    if status.worker_id == "graceful-worker"
                        && (status.status == WorkerStatus::Stopped
                            || status.status == WorkerStatus::Failed)
                    {
                        status_updated = true;
                        break;
                    }
                }
            }
