}

/// Temporary storage for chat exchange data during streaming display.
#[derive(Clone, Debug)]
struct PendingChatExchange {
    query: String,
    response_text: String,
    timestamp: String,
    tool_calls: Vec<ToolCallInfo>,
    side_effects: Vec<SideEffectInfo>,
