        // Should NOT have the right column panels
        assert!(
            !buffer_contains(&buffer, "Cost Breakdown"),
            "Wide layout should NOT show Cost Breakdown panel"
        );
        assert!(
            !buffer_contains(&buffer, "Quick Actions"),
