     1→//! Subscription tracking and management.
     2→//!
     3→//! This module provides subscription tracking functionality including:
     4→//! - Loading subscription configurations from YAML
     5→//! - Tracking usage against quotas
     6→//! - Calculating days until renewal
     7→//! - Generating alerts when quota is high or renewal is approaching
     8→
     9→use chrono::{DateTime, Datelike, Duration, Utc};
    10→use serde::{Deserialize, Serialize};
    11→use std::collections::HashMap;
    12→use std::path::Path;
    13→use tracing::{debug, info, warn};
    14→
    15→use crate::db::CostDatabase;
    16→use crate::error::{CostError, Result};
    17→use crate::models::{Subscription, SubscriptionSummary, SubscriptionType};
    18→
    19→/// Configuration for a subscription (loaded from YAML).
    20→#[derive(Debug, Clone, Serialize, Deserialize)]
    21→pub struct SubscriptionConfig {
    22→    /// Provider name (e.g., "anthropic", "openai")
    23→    pub provider: String,
    24→    /// Plan name (e.g., "max_5x", "plus")
    25→    pub plan: String,
    26→    /// Monthly token quota (for token-based plans)
    27→    #[serde(default)]
    28→    pub monthly_tokens: Option<i64>,
    29→    /// Monthly cost in USD
    30→    #[serde(default)]
    31→    pub monthly_cost: Option<f64>,
    32→    /// Renewal date (day of month or ISO date)
    33→    #[serde(default)]
    34→    pub renewal_date: Option<String>,
    35→    /// Current usage (if known)
    36→    #[serde(default)]
    37→    pub current_usage: Option<i64>,
    38→    /// Associated model (if applicable)
    39→    #[serde(default)]
    40→    pub model: Option<String>,
    41→    /// Subscription type (fixed_quota, unlimited, pay_per_use)
    42→    #[serde(default = "default_subscription_type")]
    43→    pub subscription_type: String,
    44→    /// Whether the subscription is active
    45→    #[serde(default = "default_true")]
    46→    pub active: bool,
    47→}
    48→
    49→fn default_subscription_type() -> String {
    50→    "fixed_quota".to_string()
    51→}
    52→
    53→fn default_true() -> bool {
    54→    true
    55→}
    56→
    57→/// Root configuration file structure.
    58→#[derive(Debug, Clone, Serialize, Deserialize)]
    59→pub struct SubscriptionConfigFile {
    60→    /// List of subscription configurations
    61→    pub subscriptions: Vec<SubscriptionConfig>,
    62→}
    63→
    64→/// Alert level for subscription status.
    65→#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
    66→pub enum SubscriptionAlert {
    67→    /// No alert - everything is fine
    68→    None,
    69→    /// Warning - quota usage > 80% or renewal within 3 days
    70→    Warning,
    71→    /// Critical - quota usage > 90% or renewal within 1 day
    72→    Critical,
    73→    /// Depleted - quota exhausted
    74→    Depleted,
    75→}
    76→
    77→impl SubscriptionAlert {
    78→    /// Get icon for the alert level.
    79→    pub fn icon(&self) -> &'static str {
    80→        match self {
    81→            SubscriptionAlert::None => "",
    82→            SubscriptionAlert::Warning => "⚠",
    83→            SubscriptionAlert::Critical => "🔴",
    84→            SubscriptionAlert::Depleted => "❌",
    85→        }
    86→    }
    87→
    88→    /// Check if this is an alerting state.
    89→    pub fn is_alert(&self) -> bool {
    90→        !matches!(self, SubscriptionAlert::None)
    91→    }
    92→}
    93→
    94→/// Subscription tracker that manages multiple subscriptions.
    95→pub struct SubscriptionTracker {
    96→    /// Loaded subscriptions by name
    97→    subscriptions: HashMap<String, Subscription>,
    98→    /// Path to config file
    99→    config_path: Option<std::path::PathBuf>,
   100→    /// Last load time
   101→    last_loaded: Option<DateTime<Utc>>,
   102→    /// Cache of subscription summaries for display
   103→    summary_cache: Vec<SubscriptionSummary>,
   104→}
   105→
   106→impl SubscriptionTracker {
   107→    /// Create a new empty subscription tracker.
   108→    pub fn new() -> Self {
   109→        Self {
   110→            subscriptions: HashMap::new(),
   111→            config_path: None,
   112→            last_loaded: None,
   113→            summary_cache: Vec::new(),
   114→        }
   115→    }
   116→
   117→    /// Create a tracker with configuration loaded from a file.
   118→    pub fn from_config_file<P: AsRef<Path>>(path: P) -> Result<Self> {
   119→        let mut tracker = Self::new();
   120→        tracker.config_path = Some(path.as_ref().to_path_buf());
   121→        tracker.reload()?;
   122→        Ok(tracker)
   123→    }
   124→
   125→    /// Create a tracker with default config path (~/.forge/subscriptions.yaml).
   126→    pub fn with_default_config() -> Self {
   127→        let home = std::env::var("HOME").unwrap_or_else(|_| "/home/coder".to_string());
   128→        let config_path = Path::new(&home).join(".forge").join("subscriptions.yaml");
   129→
   130→        if config_path.exists() {
   131→            match Self::from_config_file(&config_path) {
   132→                Ok(tracker) => {
   133→                    info!("Loaded {} subscriptions from {}", tracker.len(), config_path.display());
   134→                    return tracker;
   135→                }
   136→                Err(e) => {
   137→                    warn!("Failed to load subscriptions from {}: {}", config_path.display(), e);
   138→                }
   139→            }
   140→        }
   141→
   142→        // Return empty tracker if no config found
   143→        let mut tracker = Self::new();
   144→        tracker.config_path = Some(config_path);
   145→        tracker
   146→    }
   147→
   148→    /// Reload subscriptions from the config file.
   149→    pub fn reload(&mut self) -> Result<()> {
   150→        let config_path = self.config_path.as_ref().ok_or_else(|| {
   151→            CostError::Config("No config path set".to_string())
   152→        })?;
   153→
   154→        if !config_path.exists() {
   155→            debug!("Subscription config file does not exist: {}", config_path.display());
   156→            return Ok(());
   157→        }
   158→
   159→        let config_str = std::fs::read_to_string(config_path)?;
   160→        let config: SubscriptionConfigFile = serde_yaml::from_str(&config_str)?;
   161→
   162→        self.subscriptions.clear();
   163→
   164→        for sub_config in config.subscriptions {
   165→            let subscription = self.config_to_subscription(&sub_config)?;
   166→            let name = subscription.name.clone();
   167→            self.subscriptions.insert(name, subscription);
   168→        }
   169→
   170→        self.last_loaded = Some(Utc::now());
   171→        self.update_summary_cache();
   172→
   173→        info!("Loaded {} subscriptions from config", self.subscriptions.len());
   174→        Ok(())
   175→    }
   176→
   177→    /// Convert a config entry to a Subscription model.
   178→    fn config_to_subscription(&self, config: &SubscriptionConfig) -> Result<Subscription> {
   179→        let now = Utc::now();
   180→
   181→        // Parse subscription type
   182→        let subscription_type = match config.subscription_type.as_str() {
   183→            "fixed_quota" | "fixed" => SubscriptionType::FixedQuota,
   184→            "unlimited" => SubscriptionType::Unlimited,
   185→            "pay_per_use" | "payperuse" => SubscriptionType::PayPerUse,
   186→            _ => SubscriptionType::FixedQuota,
   187→        };
   188→
   189→        // Parse renewal date
   190→        let (billing_start, billing_end) = self.parse_billing_period(&config.renewal_date, now)?;
   191→
   192→        // Build subscription name from provider and plan
   193→        let name = format!("{} {}", config.provider, config.plan);
   194→
   195→        let mut subscription = Subscription::new(
   196→            name,
   197→            subscription_type,
   198→            config.monthly_cost.unwrap_or(0.0),
   199→            billing_start,
   200→            billing_end,
   201→        );
   202→
   203→        // Set model if provided
   204→        if let Some(ref model) = config.model {
   205→            subscription = subscription.with_model(model);
   206→        }
   207→
   208→        // Set quota limit if provided
   209→        if let Some(tokens) = config.monthly_tokens {
   210→            subscription = subscription.with_quota(tokens);
   211→        }
   212→
   213→        // Set current usage if provided
   214→        if let Some(usage) = config.current_usage {
   215→            subscription.quota_used = usage;
   216→        }
   217→
   218→        // Set active status
   219→        subscription.active = config.active;
   220→
   221→        Ok(subscription)
   222→    }
   223→
   224→    /// Parse billing period from renewal date string.
   225→    fn parse_billing_period(
   226→        &self,
   227→        renewal_date: &Option<String>,
   228→        now: DateTime<Utc>,
   229→    ) -> Result<(DateTime<Utc>, DateTime<Utc>)> {
   230→        let renewal = renewal_date.clone().unwrap_or_else(|| {
   231→            // Default to end of current month
   232→            format!("{}-{:02}-28", now.year(), now.month())
   233→        });
   234→
   235→        // Try to parse as ISO date (YYYY-MM-DD)
   236→        if let Ok(date) = chrono::NaiveDate::parse_from_str(&renewal, "%Y-%m-%d") {
   237→            let billing_end = date.and_hms_opt(23, 59, 59).unwrap().and_utc();
   238→            // Billing period is typically one month
   239→            let billing_start = billing_end - Duration::days(30);
   240→            return Ok((billing_start, billing_end));
   241→        }
   242→
   243→        // Try to parse as day of month (e.g., "15" for 15th)
   244→        if let Ok(day) = renewal.parse::<u32>() {
   245→            let day = day.min(28); // Clamp to 28 to avoid month issues
   246→
   247→            // Calculate next renewal date
   248→            let mut renewal_month = now.month();
   249→            let mut renewal_year = now.year();
   250→
   251→            // If the day has passed this month, use next month
   252→            if now.day() >= day {
   253→                renewal_month += 1;
   254→                if renewal_month > 12 {
   255→                    renewal_month = 1;
   256→                    renewal_year += 1;
   257→                }
   258→            }
   259→
   260→            let billing_end = chrono::NaiveDate::from_ymd_opt(renewal_year, renewal_month, day)
   261→                .unwrap_or_else(|| chrono::NaiveDate::from_ymd_opt(renewal_year, renewal_month, 28).unwrap())
   262→                .and_hms_opt(23, 59, 59)
   263→                .unwrap()
   264→                .and_utc();
   265→
   266→            let billing_start = billing_end - Duration::days(30);
   267→            return Ok((billing_start, billing_end));
   268→        }
   269→
   270→        // Default: 30 days from now
   271→        let billing_end = now + Duration::days(30);
   272→        let billing_start = now;
   273→        Ok((billing_start, billing_end))
   274→    }
   275→
   276→    /// Update the summary cache.
   277→    fn update_summary_cache(&mut self) {
   278→        self.summary_cache = self.subscriptions
   279→            .values()
   280→            .map(|s| SubscriptionSummary::from(s))
   281→            .collect();
   282→    }
   283→
   284→    /// Get all subscriptions.
   285→    pub fn get_subscriptions(&self) -> Vec<&Subscription> {
   286→        self.subscriptions.values().collect()
   287→    }
   288→
   289→    /// Get subscription summaries for display.
   290→    pub fn get_summaries(&self) -> &[SubscriptionSummary] {
   291→        &self.summary_cache
   292→    }
   293→
   294→    /// Get a subscription by name.
   295→    pub fn get_subscription(&self, name: &str) -> Option<&Subscription> {
   296→        self.subscriptions.get(name)
   297→    }
   298→
   299→    /// Get subscription count.
   300→    pub fn len(&self) -> usize {
   301→        self.subscriptions.len()
   302→    }
   303→
   304→    /// Check if there are no subscriptions.
   305→    pub fn is_empty(&self) -> bool {
   306→        self.subscriptions.is_empty()
   307→    }
   308→
   309→    /// Check if we have any active subscriptions.
   310→    pub fn has_active(&self) -> bool {
   311→        self.subscriptions.values().any(|s| s.active)
   312→    }
   313→
   314→    /// Sync subscriptions with the database.
   315→    pub fn sync_to_database(&self, db: &CostDatabase) -> Result<()> {
   316→        for subscription in self.subscriptions.values() {
   317→            db.upsert_subscription(subscription)?;
   318→        }
   319→        Ok(())
   320→    }
   321→
   322→    /// Load subscriptions from the database.
   323→    pub fn load_from_database(&mut self, db: &CostDatabase) -> Result<()> {
   324→        let db_subscriptions = db.get_active_subscriptions()?;
   325→
   326→        for sub in db_subscriptions {
   327→            let name = sub.name.clone();
   328→            self.subscriptions.insert(name, sub);
   329→        }
   330→
   331→        self.update_summary_cache();
   332→        Ok(())
   333→    }
   334→
   335→    /// Calculate days until renewal for a subscription.
   336→    pub fn days_until_renewal(&self, name: &str) -> Option<i64> {
   337→        self.subscriptions.get(name).map(|s| {
   338→            let duration = s.time_until_reset();
   339→            duration.num_days().max(0)
   340→        })
   341→    }
   342→
   343→    /// Get alert level for a subscription.
   344→    pub fn get_alert(&self, name: &str) -> SubscriptionAlert {
   345→        let Some(sub) = self.subscriptions.get(name) else {
   346→            return SubscriptionAlert::None;
   347→        };
   348→
   349→        let usage_pct = sub.usage_percentage();
   350→        let days_left = sub.time_until_reset().num_days();
   351→
   352→        // Check if depleted
   353→        if usage_pct >= 100.0 {
   354→            return SubscriptionAlert::Depleted;
   355→        }
   356→
   357→        // Check if critical (>90% usage or <1 day to renewal)
   358→        if usage_pct >= 90.0 || days_left <= 1 {
   359→            return SubscriptionAlert::Critical;
   360→        }
   361→
   362→        // Check if warning (>80% usage or <3 days to renewal)
   363→        if usage_pct >= 80.0 || days_left <= 3 {
   364→            return SubscriptionAlert::Warning;
   365→        }
   366→
   367→        SubscriptionAlert::None
   368→    }
   369→
   370→    /// Get all subscriptions with alerts.
   371→    pub fn get_alerts(&self) -> Vec<(String, SubscriptionAlert)> {
   372→        self.subscriptions
   373→            .keys()
   374→            .map(|name| {
   375→                let alert = self.get_alert(name);
   376→                (name.clone(), alert)
   377→            })
   378→            .filter(|(_, alert)| alert.is_alert())
   379→            .collect()
   380→    }
   381→
   382→    /// Check if any subscription has a critical or depleted alert.
   383→    pub fn has_critical_alert(&self) -> bool {
   384→        self.subscriptions.keys().any(|name| {
   385→            matches!(
   386→                self.get_alert(name),
   387→                SubscriptionAlert::Critical | SubscriptionAlert::Depleted
   388→            )
   389→        })
   390→    }
   391→
   392→    /// Update usage for a subscription (typically from database).
   393→    pub fn update_usage(&mut self, name: &str, quota_used: i64) {
   394→        if let Some(sub) = self.subscriptions.get_mut(name) {
   395→            sub.quota_used = quota_used;
   396→            sub.updated_at = Utc::now();
   397→            self.update_summary_cache();
   398→        }
   399→    }
   400→
   401→    /// Increment usage for a subscription.
   402→    pub fn increment_usage(&mut self, name: &str, units: i64) {
   403→        if let Some(sub) = self.subscriptions.get_mut(name) {
   404→            sub.quota_used += units;
   405→            sub.updated_at = Utc::now();
   406→            self.update_summary_cache();
   407→        }
   408→    }
   409→
   410→    /// Find subscription by model name.
   411→    pub fn find_subscription_for_model(&self, model: &str) -> Option<String> {
   412→        for (name, sub) in &self.subscriptions {
   413→            if sub.model.as_ref().map(|m| m == model).unwrap_or(false) {
   414→                return Some(name.clone());
   415→            }
   416→        }
   417→        None
   418→    }
   419→
   420→    /// Check and reset billing periods that have ended.
   421→    /// Returns the number of subscriptions that were reset.
   422→    pub fn check_and_reset_billing(&mut self, _db: &CostDatabase) -> Result<usize> {
   423→        // Check all subscriptions for expired billing periods
   424→        let now = Utc::now();
   425→        let mut reset_count = 0;
   426→
   427→        for sub in self.subscriptions.values_mut() {
   428→            if sub.billing_end <= now && sub.active {
   429→                // Reset billing period
   430→                let new_start = sub.billing_end;
   431→                let new_end = new_start + Duration::days(30);
   432→                sub.billing_start = new_start;
   433→                sub.billing_end = new_end;
   434→                sub.quota_used = 0;
   435→                sub.updated_at = now;
   436→                reset_count += 1;
   437→            }
   438→        }
   439→
   440→        if reset_count > 0 {
   441→            self.update_summary_cache();
   442→        }
   443→
   444→        Ok(reset_count)
   445→    }
