   115→
   116→/// Reset period type for subscriptions.
   117→#[derive(Debug, Clone, Copy, PartialEq, Eq)]
   118→pub enum ResetPeriod {
   119→    /// Hourly reset (e.g., ChatGPT 40 messages per 3 hours)
   120→    Hourly(u32),
   121→    /// Daily reset
   122→    Daily,
   123→    /// Weekly reset
   124→    Weekly,
   125→    /// Monthly reset
   126→    Monthly,
   127→    /// No reset (pay-per-use)
   128→    PayPerUse,
   129→}
   130→
   131→impl ResetPeriod {
   132→    /// Format the reset period for display.
   133→    pub fn display(&self) -> String {
   134→        match self {
   135→            ResetPeriod::Hourly(hours) => format!("{}hr", hours),
   136→            ResetPeriod::Daily => "Daily".to_string(),
   137→            ResetPeriod::Weekly => "Weekly".to_string(),
   138→            ResetPeriod::Monthly => "Monthly".to_string(),
   139→            ResetPeriod::PayPerUse => "Pay/Use".to_string(),
   140→        }
   141→    }
   142→}
   143→
   144→/// Status of a single subscription.
   145→#[derive(Debug, Clone)]
   146→pub struct SubscriptionStatus {
   147→    /// Service type
   148→    pub service: SubscriptionService,
   149→    /// Current usage (messages, requests, or tokens)
   150→    pub current_usage: u64,
   151→    /// Usage limit (None for pay-per-use)
   152→    pub limit: Option<u64>,
   153→    /// Unit of measurement (messages, requests, tokens)
   154→    pub unit: String,
   155→    /// When the quota resets
   156→    pub resets_at: Option<DateTime<Utc>>,
   157→    /// Reset period type
   158→    pub reset_period: ResetPeriod,
   159→    /// Whether the subscription is active
   160→    pub is_active: bool,
   161→    /// Daily spend for pay-per-use subscriptions
   162→    pub daily_spend: Option<f64>,
   163→    /// Last updated timestamp
   164→    pub last_updated: DateTime<Utc>,
   165→}
   166→
   167→impl SubscriptionStatus {
   168→    /// Create a new subscription status.
   169→    pub fn new(service: SubscriptionService) -> Self {
   170→        Self {
   171→            service,
   172→            current_usage: 0,
   173→            limit: None,
   174→            unit: "msgs".to_string(),
   175→            resets_at: None,
   176→            reset_period: ResetPeriod::Monthly,
   177→            is_active: false,
   178→            daily_spend: None,
   179→            last_updated: Utc::now(),
   180→        }
   181→    }
   182→
   183→    /// Set usage and limit.
   184→    pub fn with_usage(mut self, current: u64, limit: u64, unit: &str) -> Self {
   185→        self.current_usage = current;
   186→        self.limit = Some(limit);
   187→        self.unit = unit.to_string();
   188→        self
   189→    }
   190→
   191→    /// Set reset time.
   192→    pub fn with_reset(mut self, resets_at: DateTime<Utc>, period: ResetPeriod) -> Self {
   193→        self.resets_at = Some(resets_at);
   194→        self.reset_period = period;
   195→        self
   196→    }
   197→
   198→    /// Set as pay-per-use with daily spend.
   199→    pub fn with_pay_per_use(mut self, daily_spend: f64) -> Self {
   200→        self.limit = None;
   201→        self.daily_spend = Some(daily_spend);
   202→        self.reset_period = ResetPeriod::PayPerUse;
   203→        self
   204→    }
   205→
   206→    /// Set active status.
   207→    pub fn with_active(mut self, active: bool) -> Self {
   208→        self.is_active = active;
   209→        self
   210→    }
   211→
   212→    /// Get usage percentage (0-100).
   213→    pub fn usage_pct(&self) -> f64 {
   214→        match self.limit {
   215→            Some(limit) if limit > 0 => (self.current_usage as f64 / limit as f64) * 100.0,
   216→            _ => 0.0,
   217→        }
   218→    }
   219→
   220→    /// Get remaining usage.
   221→    pub fn remaining(&self) -> Option<u64> {
   222→        self.limit.map(|l| l.saturating_sub(self.current_usage))
   223→    }
   224→
   225→    /// Get time until reset.
   226→    pub fn time_until_reset(&self) -> Option<Duration> {
   227→        self.resets_at.map(|r| {
   228→            let now = Utc::now();
   229→            if r > now { r - now } else { Duration::zero() }
   230→        })
   231→    }
   232→
   233→    /// Format time until reset for display.
   234→    pub fn format_reset_timer(&self) -> String {
   235→        match self.time_until_reset() {
   236→            Some(duration) if duration > Duration::zero() => {
   237→                let days = duration.num_days();
   238→                let hours = duration.num_hours() % 24;
   239→                let minutes = duration.num_minutes() % 60;
   240→
   241→                if days > 0 {
   242→                    format!("{}d {}h", days, hours)
   243→                } else if hours > 0 {
   244→                    format!("{}h {}m", hours, minutes)
   245→                } else {
   246→                    format!("{}m", minutes)
   247→                }
   248→            }
   249→            Some(_) => "Resetting...".to_string(),
   250→            None => match self.reset_period {
   251→                ResetPeriod::PayPerUse => "Monthly".to_string(),
   252→                _ => "-".to_string(),
   253→            },
   254→        }
   255→    }
   256→
   257→    /// Determine the recommended action based on usage patterns.
   258→    pub fn recommended_action(&self) -> SubscriptionAction {
   259→        if !self.is_active {
   260→            return SubscriptionAction::Paused;
   261→        }
   262→
   263→        // Pay-per-use subscriptions are always "Active"
   264→        if matches!(self.reset_period, ResetPeriod::PayPerUse) {
   265→            return SubscriptionAction::Active;
   266→        }
   267→
   268→        let usage_pct = self.usage_pct();
   269→
   270→        // Check if over quota
   271→        if usage_pct >= 100.0 {
   272→            return SubscriptionAction::OverQuota;
   273→        }
   274→
   275→        // Calculate expected usage based on time remaining
   276→        if let Some(duration) = self.time_until_reset() {
   277→            let total_hours = match self.reset_period {
   278→                ResetPeriod::Hourly(h) => h as f64,
   279→                ResetPeriod::Daily => 24.0,
   280→                ResetPeriod::Weekly => 24.0 * 7.0,
   281→                ResetPeriod::Monthly => 24.0 * 30.0,
   282→                ResetPeriod::PayPerUse => return SubscriptionAction::Active,
   283→            };
   284→
   285→            let hours_remaining =
   286→                duration.num_hours() as f64 + (duration.num_minutes() % 60) as f64 / 60.0;
   287→            let hours_elapsed = total_hours - hours_remaining;
   288→            let expected_pct = if total_hours > 0.0 {
   289→                (hours_elapsed / total_hours) * 100.0
   290→            } else {
   291→                100.0
   292→            };
   293→
   294→            // Compare actual vs expected
   295→            let ratio = if expected_pct > 0.0 {
   296→                usage_pct / expected_pct
   297→            } else {
   298→                0.0
   299→            };
   300→
   301→            // Determine action based on ratio and remaining time
   302→            if usage_pct >= 95.0 {
   303→                SubscriptionAction::MaxOut
   304→            } else if ratio < 0.5 && usage_pct < 50.0 && hours_remaining < total_hours * 0.3 {
   305→                // Less than 30% time left but less than 50% used
   306→                SubscriptionAction::MaxOut
   307→            } else if ratio < 0.7 && usage_pct < 70.0 {
   308→                SubscriptionAction::Accelerate
   309→            } else {
   310→                SubscriptionAction::OnPace
   311→            }
   312→        } else {
   313→            // No reset time info - assume on pace
   314→            SubscriptionAction::OnPace
   315→        }
   316→    }
   317→
   318→    /// Get color for usage bar based on percentage.
   319→    pub fn usage_color(&self) -> Color {
   320→        let pct = self.usage_pct();
   321→        if pct >= 95.0 {
   322→            Color::Red
   323→        } else if pct >= 80.0 {
   324→            Color::LightRed
   325→        } else if pct >= 60.0 {
   326→            Color::Yellow
   327→        } else if pct >= 40.0 {
   328→            Color::Cyan
   329→        } else {
   330→            Color::Green
   331→        }
   332→    }
   333→}
   334→
   335→/// Collection of all subscription statuses.
   336→#[derive(Debug, Default)]
   337→pub struct SubscriptionData {
   338→    /// Subscription statuses by service
   339→    pub subscriptions: Vec<SubscriptionStatus>,
   340→    /// Whether data is loading
   341→    pub is_loading: bool,
   342→    /// Error message if any
   343→    pub error: Option<String>,
   344→    /// Last update timestamp
   345→    pub last_updated: Option<DateTime<Utc>>,
   346→}
   347→
   348→impl SubscriptionData {
   349→    /// Create new empty subscription data.
   350→    pub fn new() -> Self {
   351→        Self::default()
   352→    }
   353→
   354→    /// Create with loading state.
   355→    pub fn loading() -> Self {
   356→        Self {
   357→            is_loading: true,
   358→            ..Default::default()
   359→        }
   360→    }
   361→
   362→    /// Create with demo/mock data for display.
   363→    pub fn with_demo_data() -> Self {
   364→        let now = Utc::now();
   365→
   366→        let subscriptions = vec![
   367→            // Claude Pro: 328/500 messages, resets in 16 days
   368→            SubscriptionStatus::new(SubscriptionService::ClaudePro)
   369→                .with_usage(328, 500, "msgs")
   370→                .with_reset(
   371→                    now + Duration::days(16) + Duration::hours(9),
   372→                    ResetPeriod::Monthly,
   373→                )
   374→                .with_active(true),
   375→            // ChatGPT Plus: 12/40 messages per 3 hours
   376→            SubscriptionStatus::new(SubscriptionService::ChatGPTPlus)
   377→                .with_usage(12, 40, "msg/3hr")
   378→                .with_reset(
   379→                    now + Duration::hours(23) + Duration::minutes(14),
   380→                    ResetPeriod::Hourly(3),
   381→                )
   382→                .with_active(true),
   383→            // Cursor Pro: 487/500 requests
   384→            SubscriptionStatus::new(SubscriptionService::CursorPro)
   385→                .with_usage(487, 500, "reqs")
   386→                .with_reset(
   387→                    now + Duration::days(8) + Duration::hours(3),
   388→                    ResetPeriod::Monthly,
   389→                )
   390→                .with_active(true),
   391→            // DeepSeek: Pay-per-use
   392→            SubscriptionStatus::new(SubscriptionService::DeepSeekAPI)
   393→                .with_pay_per_use(0.02)
   394→                .with_active(true),
   395→        ];
   396→
   397→        Self {
   398→            subscriptions,
   399→            is_loading: false,
   400→            error: None,
   401→            last_updated: Some(now),
   402→        }
   403→    }
   404→
   405→    /// Get subscription by service type.
   406→    pub fn get(&self, service: SubscriptionService) -> Option<&SubscriptionStatus> {
   407→        self.subscriptions.iter().find(|s| s.service == service)
   408→    }
   409→
   410→    /// Check if any subscription is active.
   411→    pub fn has_active(&self) -> bool {
   412→        self.subscriptions.iter().any(|s| s.is_active)
   413→    }
   414→
   415→    /// Count active subscriptions.
   416→    pub fn active_count(&self) -> usize {
   417→        self.subscriptions.iter().filter(|s| s.is_active).count()
   418→    }
   419→
   420→    /// Check if we have data.
   421→    pub fn has_data(&self) -> bool {
   422→        !self.subscriptions.is_empty()
   423→    }
   424→}
   425→
   426→/// Render a horizontal progress bar.
   427→pub fn render_usage_bar(pct: f64, width: usize, color: Color) -> Line<'static> {
   428→    let pct = pct.clamp(0.0, 100.0);
   429→    let filled = ((pct / 100.0) * width as f64).round() as usize;
   430→    let empty = width.saturating_sub(filled);
   431→
   432→    let filled_str: String = "█".repeat(filled);
   433→    let empty_str: String = "░".repeat(empty);
   434→
   435→    Line::from(vec![
   436→        Span::styled(filled_str, Style::default().fg(color)),
   437→        Span::styled(empty_str, Style::default().fg(Color::DarkGray)),
   438→    ])
   439→}
   440→
   441→/// Subscription panel widget.
   442→pub struct SubscriptionPanel<'a> {
   443→    data: &'a SubscriptionData,
   444→    focused: bool,
   445→}
   446→
   447→impl<'a> SubscriptionPanel<'a> {
   448→    /// Create a new subscription panel.
   449→    pub fn new(data: &'a SubscriptionData) -> Self {
   450→        Self {
   451→            data,
   452→            focused: false,
   453→        }
   454→    }
   455→
   456→    /// Set focus state.
   457→    pub fn focused(mut self, focused: bool) -> Self {
   458→        self.focused = focused;
   459→        self
   460→    }
   461→
   462→    /// Render the subscription table.
   463→    fn render_table(&self, area: Rect, buf: &mut Buffer) {
   464→        if self.data.subscriptions.is_empty() {
   465→            let msg = Paragraph::new("No subscription data available")
   466→                .style(Style::default().fg(Color::Gray));
   467→            msg.render(area, buf);
   468→            return;
   469→        }
   470→
   471→        // Build table rows
   472→        let rows: Vec<Row> = self
   473→            .data
   474→            .subscriptions
   475→            .iter()
   476→            .map(|sub| {
   477→                let service = sub.service.display_name();
   478→
   479→                // Usage column with bar
   480→                let usage_str = if let Some(limit) = sub.limit {
   481→                    format!("{}/{}", sub.current_usage, limit)
   482→                } else if let Some(spend) = sub.daily_spend {
   483→                    format!("${:.2}/d", spend)
   484→                } else {
   485→                    "-".to_string()
   486→                };
   487→
   488→                // Limit/unit column
   489→                let limit_str = if sub.limit.is_some() {
   490→                    sub.unit.clone()
   491→                } else {
   492→                    "∞".to_string()
   493→                };
   494→
   495→                // Reset timer
   496→                let reset_str = sub.format_reset_timer();
   497→
   498→                // Action with icon
   499→                let action = sub.recommended_action();
   500→                let action_str = format!("{} {}", action.icon(), action.description());
   501→
   502→                Row::new(vec![
   503→                    service.to_string(),
   504→                    usage_str,
   505→                    limit_str,
   506→                    reset_str,
   507→                    action_str,
   508→                ])
   509→                .style(if sub.is_active {
   510→                    Style::default()
   511→                } else {
   512→                    Style::default().fg(Color::DarkGray)
   513→                })
   514→            })
   515→            .collect();
   516→
   517→        let header = Row::new(vec!["Service", "Usage", "Limit", "Resets", "Action"])
   518→            .style(
   519→                Style::default()
   520→                    .fg(Color::Gray)
   521→                    .add_modifier(Modifier::BOLD),
   522→            )
   523→            .bottom_margin(0);
   524→
   525→        let widths = [
   526→            Constraint::Length(12),
   527→            Constraint::Length(9),
   528→            Constraint::Length(7),
   529→            Constraint::Length(10),
   530→            Constraint::Length(11),
   531→        ];
   532→
   533→        let table = Table::new(rows, widths).header(header).column_spacing(1);
   534→
   535→        ratatui::widgets::Widget::render(table, area, buf);
   536→    }
   537→
   538→    /// Render usage bars below the table.
   539→    #[allow(dead_code)]
   540→    fn render_usage_bars(&self, area: Rect, buf: &mut Buffer) {
   541→        let mut lines = Vec::new();
   542→
   543→        for sub in &self.data.subscriptions {
   544→            if sub.limit.is_some() {
   545→                let pct = sub.usage_pct();
   546→                let color = sub.usage_color();
   547→                let bar_width = 15.min(area.width.saturating_sub(20) as usize);
   548→
   549→                // Service name and bar
   550→                let bar = render_usage_bar(pct, bar_width, color);
   551→                lines.push(Line::from(vec![Span::styled(
   552→                    format!("{:<12}", sub.service.short_name()),
   553→                    Style::default().fg(Color::White),
   554→                )]));
   555→                lines.push(bar);
   556→                lines.push(Line::from(vec![Span::styled(
   557→                    format!(
   558→                        "{:>5}/{:<5} ({:.0}%)",
   559→                        sub.current_usage,
   560→                        sub.limit.unwrap_or(0),
   561→                        pct
   562→                    ),
   563→                    Style::default().fg(Color::Gray),
   564→                )]));
   565→                lines.push(Line::from(""));
   566→            }
   567→        }
   568→
   569→        if lines.is_empty() {
   570→            lines.push(Line::from(Span::styled(
   571→                "No usage data",
   572→                Style::default().fg(Color::Gray),
   573→            )));
   574→        }
   575→
   576→        let paragraph = Paragraph::new(lines);
   577→        paragraph.render(area, buf);
   578→    }
   579→}
   580→
   581→impl Widget for SubscriptionPanel<'_> {
   582→    fn render(self, area: Rect, buf: &mut Buffer) {
   583→        // Enhanced focus indicator: "▶" arrow for focused (clearer than diamond), "▪" for unfocused
   584→        let focus_icon = if self.focused { "▶" } else { "▪" };
   585→
   586→        // Border type: Double border for focused (highly visible), Normal for unfocused
   587→        let border_type = if self.focused {
   588→            BorderType::Double
   589→        } else {
   590→            BorderType::Plain
   591→        };
   592→
   593→        // Border style: bright cyan with bold for focused, dim for unfocused
   594→        let border_style = if self.focused {
   595→            Style::default()
   596→                .fg(Color::Cyan)
   597→                .add_modifier(Modifier::BOLD)
   598→        } else {
   599→            Style::default().fg(Color::DarkGray)
   600→        };
   601→
   602→        // Title style: bold + underlined for focused, dim for unfocused
   603→        let title_style = if self.focused {
   604→            Style::default()
   605→                .fg(Color::Cyan)
   606→                .add_modifier(Modifier::BOLD | Modifier::UNDERLINED)
   607→        } else {
   608→            Style::default().fg(Color::Rgb(80, 80, 80))
   609→        };
   610→
   611→        let block = Block::default()
   612→            .borders(Borders::ALL)
   613→            .border_type(border_type)
   614→            .border_style(border_style)
   615→            .title(Span::styled(
   616→                format!(" {} Subscription Status ", focus_icon),
   617→                title_style,
   618→            ));
   619→
   620→        let inner = block.inner(area);
   621→        block.render(area, buf);
   622→
   623→        // Handle special states
   624→        if self.data.is_loading {
   625→            let loading = Paragraph::new("Loading subscription data...")
   626→                .style(Style::default().fg(Color::Yellow));
   627→            loading.render(inner, buf);
   628→            return;
   629→        }
   630→
   631→        if let Some(ref error) = self.data.error {
   632→            let err =
   633→                Paragraph::new(format!("Error: {}", error)).style(Style::default().fg(Color::Red));
   634→            err.render(inner, buf);
   635→            return;
   636→        }
   637→
   638→        if !self.data.has_data() {
   639→            let no_data = Paragraph::new(
   640→                "No subscription data.\n\n\
   641→                 Configure subscriptions in:\n\
   642→                 ~/.forge/subscriptions.yaml",
   643→            )
   644→            .style(Style::default().fg(Color::Gray));
   645→            no_data.render(inner, buf);
   646→            return;
   647→        }
   648→
   649→        // Render the table
   650→        self.render_table(inner, buf);
   651→    }
   652→}
   653→
   654→/// Compact subscription summary widget for overview panel.
   655→pub struct SubscriptionSummaryCompact<'a> {
   656→    data: &'a SubscriptionData,
   657→}
   658→
   659→impl<'a> SubscriptionSummaryCompact<'a> {
   660→    /// Create a new compact subscription summary.
   661→    pub fn new(data: &'a SubscriptionData) -> Self {
   662→        Self { data }
   663→    }
   664→}
   665→
   666→impl Widget for SubscriptionSummaryCompact<'_> {
   667→    fn render(self, area: Rect, buf: &mut Buffer) {
   668→        if self.data.is_loading {
   669→            let loading = Paragraph::new("Loading...").style(Style::default().fg(Color::Yellow));
   670→            loading.render(area, buf);
   671→            return;
   672→        }
   673→
   674→        if !self.data.has_data() {
   675→            let no_data =
   676→                Paragraph::new("No subscription data").style(Style::default().fg(Color::Gray));
   677→            no_data.render(area, buf);
   678→            return;
   679→        }
   680→
   681→        let mut lines = Vec::new();
   682→
   683→        for sub in &self.data.subscriptions {
   684→            if !sub.is_active {
   685→                continue;
   686→            }
   687→
   688→            let action = sub.recommended_action();
   689→
   690→            if let Some(limit) = sub.limit {
   691→                let pct = sub.usage_pct();
   692→                let bar_width = 9.min(area.width.saturating_sub(14) as usize);
   693→                let filled = ((pct / 100.0) * bar_width as f64).round() as usize;
   694→                let empty = bar_width.saturating_sub(filled);
   695→
   696→                let bar = format!("{}{}", "█".repeat(filled), "░".repeat(empty));
   697→
   698→                lines.push(Line::from(vec![
   699→                    Span::styled(
   700→                        format!("{:<12}", sub.service.short_name()),
   701→                        Style::default().fg(Color::White),
   702→                    ),
   703→                    Span::styled(bar, Style::default().fg(sub.usage_color())),
   704→                    Span::raw(" "),
   705→                    Span::styled(
   706→                        format!("{}/{}", sub.current_usage, limit),
   707→                        Style::default().fg(Color::Gray),
   708→                    ),
   709→                ]));
   710→
   711→                lines.push(Line::from(vec![
   712→                    Span::raw("             "),
   713→                    Span::styled(sub.format_reset_timer(), Style::default().fg(Color::Gray)),
   714→                    Span::raw("  "),
   715→                    Span::styled(
   716→                        format!("{} {}", action.icon(), action.description()),
   717→                        Style::default().fg(action.color()),
   718→                    ),
   719→                ]));
   720→            } else if let Some(spend) = sub.daily_spend {
   721→                // Pay-per-use display
   722→                lines.push(Line::from(vec![
   723→                    Span::styled(
   724→                        format!("{:<12}", sub.service.short_name()),
   725→                        Style::default().fg(Color::White),
   726→                    ),
   727→                    Span::styled("Pay/Use", Style::default().fg(Color::Gray)),
   728→                    Span::raw("  "),
   729→                    Span::styled(format!("${:.2}/d", spend), Style::default().fg(Color::Cyan)),
   730→                ]));
   731→
   732→                lines.push(Line::from(vec![
   733→                    Span::raw("             "),
   734→                    Span::styled("Monthly", Style::default().fg(Color::Gray)),
   735→                    Span::raw("  "),
   736→                    Span::styled(
   737→                        format!("{} {}", action.icon(), action.description()),
   738→                        Style::default().fg(action.color()),
   739→                    ),
   740→                ]));
   741→            }
   742→
   743→            lines.push(Line::from(""));
   744→        }
   745→
   746→        // Remove trailing empty line
   747→        if lines.last().map_or(false, |l| l.spans.is_empty()) {
   748→            lines.pop();
   749→        }
   750→
   751→        let paragraph = Paragraph::new(lines);
   752→        paragraph.render(area, buf);
   753→    }
   754→}
   755→
   756→/// Format subscription data for text-based display in the Utilization panel.
   757→pub fn format_subscription_summary(data: &SubscriptionData) -> String {
   758→    if data.is_loading {
   759→        return "Loading subscription data...".to_string();
   760→    }
   761→
   762→    if !data.has_data() {
   763→        return "No subscriptions configured.\n\n\
   764→                Configure subscriptions in:\n\
   765→                ~/.forge/subscriptions.yaml"
   766→            .to_string();
   767→    }
   768→
   769→    let mut lines = Vec::new();
   770→
   771→    lines.push("Subscription Status:".to_string());
   772→    lines.push(String::new());
   773→
   774→    for sub in &data.subscriptions {
   775→        if !sub.is_active {
   776→            continue;
   777→        }
   778→
   779→        let action = sub.recommended_action();
   780→
   781→        if let Some(limit) = sub.limit {
   782→            let pct = sub.usage_pct();
   783→            let bar_width: usize = 10;
   784→            let filled = ((pct / 100.0) * bar_width as f64).round() as usize;
   785→            let empty = bar_width.saturating_sub(filled);
   786→            let bar = format!("[{}{}]", "█".repeat(filled), "░".repeat(empty));
   787→
   788→            lines.push(format!(
   789→                "{} {} {}/{}",
   790→                sub.service.short_name(),
   791→                bar,
   792→                sub.current_usage,
   793→                limit
   794→            ));
   795→            lines.push(format!(
   796→                "  Reset: {}  {} {}",
   797→                sub.format_reset_timer(),
   798→                action.icon(),
   799→                action.description()
   800→            ));
   801→        } else if let Some(spend) = sub.daily_spend {
   802→            lines.push(format!(
   803→                "{} [Pay/Use] ${:.2}/day",
   804→                sub.service.short_name(),
   805→                spend
   806→            ));
   807→            lines.push(format!(
   808→                "  Billing: Monthly  {} {}",
   809→                action.icon(),
   810→                action.description()
   811→            ));
   812→        }
   813→
   814→        lines.push(String::new());
   815→    }
   816→
   817→    // Remove trailing empty line
   818→    if lines.last().map_or(false, |l| l.is_empty()) {
   819→        lines.pop();
   820→    }
   821→
   822→    lines.join("\n")
   823→}
