     1→//! Advanced health monitoring for workers with auto-recovery.
     2→//!
     3→//! This module implements comprehensive health monitoring for AI coding workers
     4→//! with configurable health metrics, recovery policies, and visual indicators.
     5→//!
     6→//! ## Health Metrics
     7→//!
     8→//! 1. **Process Health**: PID exists, not zombie
     9→//! 2. **Activity Health**: Last activity within threshold
    10→//! 3. **Memory Health**: RSS below limit (configurable)
    11→//! 4. **Response Health**: Responds to SIGUSR1 ping within timeout
    12→//! 5. **Task Health**: No stuck tasks > 30 minutes
    13→//!
    14→//! ## Recovery Actions
    15→//!
    16→//! The health monitor supports configurable recovery actions:
    17→//! - **Warn**: Log warning and show yellow indicator
    18→//! - **Restart**: Kill and respawn worker (after 2+ failed checks)
    19→//! - **Escalate**: Route to different model tier
    20→//! - **Alert**: Send notification (future: Slack/Discord)
    21→//!
    22→//! Per ADR 0014: Automatic recovery is opt-in. By default, visibility first.
    23→//! Health status is displayed prominently but actions require user confirmation.
    24→//!
    25→//! ## Usage
    26→//!
    27→//! ```no_run
    28→//! use forge_worker::health::{HealthMonitor, HealthMonitorConfig};
    29→//! use forge_core::status::StatusReader;
    30→//!
    31→//! fn main() -> forge_core::Result<()> {
    32→//!     let config = HealthMonitorConfig::default();
    33→//!     let mut monitor = HealthMonitor::new(config)?;
    34→//!
    35→//!     // Check health of all workers
    36→//!     let results = monitor.check_all_health()?;
    37→//!     for (worker_id, health) in results {
    38→//!         println!("{}: healthy={} score={:.2}",
    39→//!             worker_id, health.is_healthy, health.health_score);
    40→//!     }
    41→//!
    42→//!     Ok(())
    43→//! }
    44→//! ```
    45→
    46→use chrono::{DateTime, Utc};
    47→use serde::{Deserialize, Serialize};
    48→use std::collections::HashMap;
    49→use std::path::PathBuf;
    50→use std::process::Command;
    51→use tracing::{debug, info};
    52→
    53→use forge_core::status::{StatusReader, WorkerStatusInfo};
    54→use forge_core::types::WorkerStatus;
    55→
    56→/// Default health check interval in seconds.
    57→pub const DEFAULT_CHECK_INTERVAL_SECS: u64 = 30;
    58→
    59→/// Default stale activity threshold in seconds (15 minutes).
    60→pub const DEFAULT_STALE_THRESHOLD_SECS: i64 = 900;
    61→
    62→/// Default memory warning limit in MB (4GB).
    63→/// Workers exceeding this will trigger alerts.
    64→pub const DEFAULT_MEMORY_LIMIT_MB: u64 = 4096;
    65→
    66→/// Hard memory kill limit in MB (8GB).
    67→/// Workers exceeding this will be forcefully terminated.
    68→pub const DEFAULT_MEMORY_KILL_LIMIT_MB: u64 = 8192;
    69→
    70→/// Default maximum recovery attempts.
    71→pub const DEFAULT_MAX_RECOVERY_ATTEMPTS: u8 = 3;
    72→
    73→/// Default response ping timeout in milliseconds.
    74→pub const DEFAULT_RESPONSE_TIMEOUT_MS: u64 = 5000;
    75→
    76→/// Default consecutive failures before auto-restart.
    77→pub const DEFAULT_AUTO_RESTART_AFTER_FAILURES: u8 = 2;
    78→
    79→/// Configuration for health monitoring.
    80→#[derive(Debug, Clone, Serialize, Deserialize)]
    81→pub struct HealthMonitorConfig {
    82→    /// Health check interval in seconds
    83→    pub check_interval_secs: u64,
    84→
    85→    /// Stale activity threshold in seconds
    86→    pub stale_activity_threshold_secs: i64,
    87→
    88→    /// Memory warning limit in MB (0 = no limit)
    89→    /// Workers exceeding this will trigger warnings/alerts.
    90→    pub memory_limit_mb: u64,
    91→
    92→    /// Memory kill limit in MB (0 = no limit)
    93→    /// Workers exceeding this will be forcefully terminated.
    94→    /// Default: 8GB - designed to catch runaway processes.
    95→    pub memory_kill_limit_mb: u64,
    96→
    97→    /// Maximum recovery attempts before escalation
    98→    pub max_recovery_attempts: u8,
    99→
   100→    /// Enable PID existence check
   101→    pub enable_pid_check: bool,
   102→
   103→    /// Enable log activity check
   104→    pub enable_activity_check: bool,
   105→
   106→    /// Enable memory check
   107→    pub enable_memory_check: bool,
   108→
   109→    /// Enable task stuck check
   110→    pub enable_task_check: bool,
   111→
   112→    /// Task stuck threshold in minutes
   113→    pub task_stuck_threshold_mins: i64,
   114→
   115→    /// Enable response ping check (SIGUSR1)
   116→    pub enable_response_check: bool,
   117→
   118→    /// Response ping timeout in milliseconds
   119→    pub response_timeout_ms: u64,
   120→
   121→    /// Enable automatic recovery (restart after failures)
   122→    pub enable_auto_recovery: bool,
   123→
   124→    /// Number of consecutive failures before auto-restart
   125→    pub auto_restart_after_failures: u8,
   126→}
   127→
   128→impl Default for HealthMonitorConfig {
   129→    fn default() -> Self {
   130→        Self {
   131→            check_interval_secs: DEFAULT_CHECK_INTERVAL_SECS,
   132→            stale_activity_threshold_secs: DEFAULT_STALE_THRESHOLD_SECS,
   133→            memory_limit_mb: DEFAULT_MEMORY_LIMIT_MB,
   134→            memory_kill_limit_mb: DEFAULT_MEMORY_KILL_LIMIT_MB,
   135→            max_recovery_attempts: DEFAULT_MAX_RECOVERY_ATTEMPTS,
   136→            enable_pid_check: true,
   137→            enable_activity_check: true,
   138→            enable_memory_check: true, // Enabled by default for memory monitoring
   139→            enable_task_check: true,
   140→            task_stuck_threshold_mins: 30,
   141→            enable_response_check: false, // Disabled by default - requires signal handling
   142→            response_timeout_ms: DEFAULT_RESPONSE_TIMEOUT_MS,
   143→            enable_auto_recovery: false, // Disabled by default per ADR 0014
   144→            auto_restart_after_failures: DEFAULT_AUTO_RESTART_AFTER_FAILURES,
   145→        }
   146→    }
   147→}
   148→
   149→/// Types of health checks that can be performed.
   150→#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
   151→#[serde(rename_all = "snake_case")]
   152→pub enum HealthCheckType {
   153→    /// Check if PID exists and is not a zombie
   154→    PidExists,
   155→    /// Check if last activity is within threshold
   156→    ActivityFresh,
   157→    /// Check if memory usage is below limit
   158→    MemoryUsage,
   159→    /// Check if current task is not stuck
   160→    TaskProgress,
   161→    /// Check if tmux session exists
   162→    TmuxSession,
   163→    /// Check if worker responds to ping
   164→    ResponseHealth,
   165→}
   166→
   167→impl std::fmt::Display for HealthCheckType {
   168→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
   169→        match self {
   170→            Self::PidExists => write!(f, "PID"),
   171→            Self::ActivityFresh => write!(f, "Activity"),
   172→            Self::MemoryUsage => write!(f, "Memory"),
   173→            Self::TaskProgress => write!(f, "Task"),
   174→            Self::TmuxSession => write!(f, "Session"),
   175→            Self::ResponseHealth => write!(f, "Response"),
   176→        }
   177→    }
   178→}
   179→
   180→/// Types of health errors.
   181→#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
   182→#[serde(rename_all = "snake_case")]
   183→pub enum HealthErrorType {
   184→    /// Process has died
   185→    DeadProcess,
   186→    /// No activity for too long
   187→    StaleActivity,
   188→    /// Memory usage too high
   189→    HighMemory,
   190→    /// Task stuck for too long
   191→    StuckTask,
   192→    /// Tmux session missing
   193→    MissingSession,
   194→    /// Worker not responding to ping
   195→    Unresponsive,
   196→    /// Unknown error
   197→    Unknown,
   198→}
   199→
   200→impl std::fmt::Display for HealthErrorType {
   201→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
   202→        match self {
   203→            Self::DeadProcess => write!(f, "dead process"),
   204→            Self::StaleActivity => write!(f, "stale activity"),
   205→            Self::HighMemory => write!(f, "high memory"),
   206→            Self::StuckTask => write!(f, "stuck task"),
   207→            Self::MissingSession => write!(f, "missing session"),
   208→            Self::Unresponsive => write!(f, "unresponsive"),
   209→            Self::Unknown => write!(f, "unknown"),
   210→        }
   211→    }
   212→}
   213→
   214→/// Result of a single health check.
   215→#[derive(Debug, Clone, Serialize, Deserialize)]
   216→pub struct HealthCheckResult {
   217→    /// Type of check performed
   218→    pub check_type: HealthCheckType,
   219→    /// Whether the check passed
   220→    pub passed: bool,
   221→    /// Error type if check failed
   222→    pub error_type: Option<HealthErrorType>,
   223→    /// Human-readable error message
   224→    pub error_message: Option<String>,
   225→    /// Timestamp of the check
   226→    pub timestamp: DateTime<Utc>,
   227→}
