   268→/// Aggregated health status for a worker.
   269→#[derive(Debug, Clone, Serialize, Deserialize)]
   270→pub struct WorkerHealthStatus {
   271→    /// Worker identifier
   272→    pub worker_id: String,
   273→    /// Overall health status
   274→    pub is_healthy: bool,
   275→    /// Health score (0.0 - 1.0)
   276→    pub health_score: f32,
   277→    /// Individual check results
   278→    pub check_results: Vec<HealthCheckResult>,
   279→    /// Failed check types
   280→    pub failed_checks: Vec<HealthCheckType>,
   281→    /// Primary error message
   282→    pub primary_error: Option<String>,
   283→    /// Actionable guidance for user
   284→    pub guidance: Vec<String>,
   285→    /// Last health check timestamp
   286→    pub last_checked: DateTime<Utc>,
   287→    /// Recovery attempts count
   288→    pub recovery_attempts: u8,
   289→    /// Consecutive health check failures
   290→    pub consecutive_failures: u8,
   291→    /// Whether auto-restart should be triggered
   292→    pub should_auto_restart: bool,
   293→    /// Whether recovery is exhausted (max attempts reached)
   294→    pub recovery_exhausted: bool,
   295→    /// Whether the worker is paused
   296→    pub is_paused: bool,
   297→    /// Timestamp when the worker was paused (if paused)
   298→    pub paused_at: Option<DateTime<Utc>>,
   299→    /// Reason for pausing the worker (if paused)
   300→    pub pause_reason: Option<String>,
   301→}
   302→
   303→impl WorkerHealthStatus {
   304→    /// Create a new health status for a worker.
   305→    pub fn new(worker_id: impl Into<String>) -> Self {
   306→        Self {
   307→            worker_id: worker_id.into(),
   308→            is_healthy: true,
   309→            health_score: 1.0,
   310→            check_results: Vec::new(),
   311→            failed_checks: Vec::new(),
   312→            primary_error: None,
   313→            guidance: Vec::new(),
   314→            last_checked: Utc::now(),
   315→            recovery_attempts: 0,
   316→            consecutive_failures: 0,
   317→            should_auto_restart: false,
   318→            recovery_exhausted: false,
   319→            is_paused: false,
   320→            paused_at: None,
   321→            pause_reason: None,
   322→        }
   323→    }
   324→
   325→    /// Add a check result and update health score.
   326→    pub fn add_result(&mut self, result: HealthCheckResult) {
   327→        if !result.passed {
   328→            self.failed_checks.push(result.check_type);
   329→            self.is_healthy = false;
   330→        }
   331→        self.check_results.push(result);
   332→        self.recalculate_score();
   333→    }
   334→
   335→    /// Recalculate health score based on check results.
   336→    fn recalculate_score(&mut self) {
   337→        if self.check_results.is_empty() {
   338→            self.health_score = 1.0;
   339→            return;
   340→        }
   341→
   342→        let passed = self.check_results.iter().filter(|r| r.passed).count();
   343→        let total = self.check_results.len();
   344→        self.health_score = passed as f32 / total as f32;
   345→    }
   346→
   347→    /// Get health indicator emoji for TUI display.
   348→    pub fn health_indicator(&self) -> &'static str {
   349→        if self.health_score >= 0.8 {
   350→            "●" // Green - healthy
   351→        } else if self.health_score >= 0.5 {
   352→            "◐" // Yellow - degraded
   353→        } else {
   354→            "○" // Red - unhealthy
   355→        }
   356→    }
   357→
   358→    /// Get health level for coloring.
   359→    pub fn health_level(&self) -> HealthLevel {
   360→        if self.health_score >= 0.8 {
   361→            HealthLevel::Healthy
   362→        } else if self.health_score >= 0.5 {
   363→            HealthLevel::Degraded
   364→        } else {
   365→            HealthLevel::Unhealthy
   366→        }
   367→    }
   368→
   369→    /// Generate actionable guidance based on failed checks.
   370→    pub fn generate_guidance(&mut self) {
   371→        self.guidance.clear();
   372→
   373→        for check_type in &self.failed_checks {
   374→            match check_type {
   375→                HealthCheckType::PidExists => {
   376→                    self.guidance.push("Process died - restart the worker".to_string());
   377→                }
   378→                HealthCheckType::ActivityFresh => {
   379→                    self.guidance.push("Worker may be stuck - check logs".to_string());
   380→                }
   381→                HealthCheckType::MemoryUsage => {
   382→                    self.guidance.push("Memory usage high - consider restart".to_string());
   383→                }
   384→                HealthCheckType::TaskProgress => {
   385→                    self.guidance.push("Task may be stuck - verify progress".to_string());
   386→                }
   387→                HealthCheckType::TmuxSession => {
   388→                    self.guidance.push("Session missing - restart required".to_string());
   389→                }
   390→                HealthCheckType::ResponseHealth => {
   391→                    self.guidance.push("Worker not responding - check if hung".to_string());
   392→                }
   393→            }
   394→        }
   395→
   396→        // Set primary error
   397→        if let Some(first_failed) = self.check_results.iter().find(|r| !r.passed) {
   398→            self.primary_error = first_failed.error_message.clone();
   399→        }
   400→    }
   401→}
   402→
   403→/// Health level for coloring and display.
   404→#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
   405→pub enum HealthLevel {
   406→    /// Healthy (green)
   407→    Healthy,
   408→    /// Degraded (yellow)
   409→    Degraded,
   410→    /// Unhealthy (red)
   411→    Unhealthy,
   412→}
