   414→/// The health monitoring engine.
   415→#[derive(Debug)]
   416→pub struct HealthMonitor {
   417→    /// Configuration
   418→    config: HealthMonitorConfig,
   419→    /// Status reader for worker status files
   420→    status_reader: StatusReader,
   421→    /// Log directory for activity checks
   422→    log_dir: PathBuf,
   423→    /// Recovery attempt tracking per worker
   424→    recovery_attempts: HashMap<String, u8>,
   425→    /// Consecutive failure tracking per worker
   426→    consecutive_failures: HashMap<String, u8>,
   427→}
   428→
   429→impl HealthMonitor {
   430→    /// Create a new health monitor with default configuration.
   431→    pub fn new(config: HealthMonitorConfig) -> forge_core::Result<Self> {
   432→        let status_reader = StatusReader::new(None)?;
   433→
   434→        let home = std::env::var("HOME").map_err(|_| forge_core::ForgeError::ConfigMissingField {
   435→            field: "HOME environment variable".to_string(),
   436→        })?;
   437→        let log_dir = PathBuf::from(home).join(".forge").join("logs");
   438→
   439→        Ok(Self {
   440→            config,
   441→            status_reader,
   442→            log_dir,
   443→            recovery_attempts: HashMap::new(),
   444→            consecutive_failures: HashMap::new(),
   445→        })
   446→    }
   447→
   448→    /// Create a health monitor with custom directories.
   449→    pub fn with_dirs(
   450→        config: HealthMonitorConfig,
   451→        status_dir: PathBuf,
   452→        log_dir: PathBuf,
   453→    ) -> forge_core::Result<Self> {
   454→        let status_reader = StatusReader::new(Some(status_dir))?;
   455→
   456→        Ok(Self {
   457→            config,
   458→            status_reader,
   459→            log_dir,
   460→            recovery_attempts: HashMap::new(),
   461→            consecutive_failures: HashMap::new(),
   462→        })
   463→    }
   464→
   465→    /// Check health of all known workers.
   466→    pub fn check_all_health(&mut self) -> forge_core::Result<HashMap<String, WorkerHealthStatus>> {
   467→        let workers = self.status_reader.read_all()?;
   468→        let mut results = HashMap::new();
   469→
   470→        for worker in workers {
   471→            let health = self.check_worker_health(&worker);
   472→            results.insert(worker.worker_id.clone(), health);
   473→        }
   474→
   475→        Ok(results)
   476→    }
   477→
   478→    /// Check health of a specific worker.
   479→    pub fn check_worker_health(&mut self, worker: &WorkerStatusInfo) -> WorkerHealthStatus {
   480→        let mut status = WorkerHealthStatus::new(&worker.worker_id);
   481→
   482→        // Carry over recovery attempts
   483→        if let Some(&attempts) = self.recovery_attempts.get(&worker.worker_id) {
   484→            status.recovery_attempts = attempts;
   485→        }
   486→
   487→        // Carry over consecutive failures
   488→        if let Some(&failures) = self.consecutive_failures.get(&worker.worker_id) {
   489→            status.consecutive_failures = failures;
   490→        }
   491→
   492→        // Track paused status from worker info
   493→        status.is_paused = worker.status.is_paused();
   494→        status.paused_at = worker.paused_at;
   495→        status.pause_reason = worker.pause_reason.clone();
   496→
   497→        // Run health checks
   498→        if self.config.enable_pid_check {
   499→            let result = self.check_pid_exists(worker);
   500→            status.add_result(result);
   501→        }
   502→
   503→        if self.config.enable_activity_check {
   504→            let result = self.check_activity_fresh(worker);
   505→            status.add_result(result);
   506→        }
   507→
   508→        if self.config.enable_memory_check {
   509→            let result = self.check_memory_usage(worker);
   510→            status.add_result(result);
   511→        }
   512→
   513→        if self.config.enable_task_check {
   514→            let result = self.check_task_progress(worker);
   515→            status.add_result(result);
   516→        }
   517→
   518→        if self.config.enable_response_check {
   519→            let result = self.check_response_health(worker);
   520→            status.add_result(result);
   521→        }
   522→
   523→        // Update consecutive failure tracking
   524→        if status.is_healthy {
   525→            // Reset consecutive failures on healthy check
   526→            self.consecutive_failures.remove(&worker.worker_id);
   527→            status.consecutive_failures = 0;
   528→        } else {
   529→            // Increment consecutive failures
   530→            let failures = self
   531→                .consecutive_failures
   532→                .entry(worker.worker_id.clone())
   533→                .or_insert(0);
   534→            *failures = failures.saturating_add(1);
   535→            status.consecutive_failures = *failures;
   536→
   537→            // Check if auto-restart should be triggered
   538→            if self.config.enable_auto_recovery
   539→                && *failures >= self.config.auto_restart_after_failures
   540→            {
   541→                status.should_auto_restart = true;
   542→                info!(
   543→                    worker_id = %worker.worker_id,
   544→                    consecutive_failures = *failures,
   545→                    threshold = self.config.auto_restart_after_failures,
   546→                    "Auto-restart triggered after consecutive failures"
   547→                );
   548→            }
   549→        }
   550→
   551→        // Check if recovery is exhausted
   552→        status.recovery_exhausted =
   553→            status.recovery_attempts >= self.config.max_recovery_attempts;
   554→
   555→        // Generate guidance based on results
   556→        status.generate_guidance();
   557→        status.last_checked = Utc::now();
   558→
   559→        debug!(
   560→            worker_id = %worker.worker_id,
   561→            is_healthy = status.is_healthy,
   562→            health_score = status.health_score,
   563→            failed_checks = ?status.failed_checks,
   564→            consecutive_failures = status.consecutive_failures,
   565→            is_paused = status.is_paused,
   566→            "Health check completed"
   567→        );
   568→
   569→        status
   570→    }
   571→
   572→    /// Check if worker responds to ping (SIGUSR1).
   573→    /// This is a placeholder that always passes - actual implementation requires
   574→    /// workers to set up a signal handler and update a response file.
   575→    fn check_response_health(&self, worker: &WorkerStatusInfo) -> HealthCheckResult {
   576→        let Some(_pid) = worker.pid else {
   577→            return HealthCheckResult::skipped(HealthCheckType::ResponseHealth);
   578→        };
   579→
   580→        // Check if response file exists and is recent
   581→        let response_file = self.log_dir.join(format!("{}.response", worker.worker_id));
   582→
   583→        if let Ok(metadata) = std::fs::metadata(&response_file) {
   584→            if let Ok(modified) = metadata.modified() {
   585→                let elapsed = modified.elapsed().unwrap_or(std::time::Duration::MAX);
   586→                let timeout = std::time::Duration::from_millis(self.config.response_timeout_ms);
   587→
   588→                if elapsed < timeout {
   589→                    return HealthCheckResult::passed(HealthCheckType::ResponseHealth);
   590→                } else {
   591→                    return HealthCheckResult::failed(
   592→                        HealthCheckType::ResponseHealth,
   593→                        HealthErrorType::Unresponsive,
   594→                        format!(
   595→                            "Worker response file is {}ms old (timeout: {}ms)",
   596→                            elapsed.as_millis(),
   597→                            self.config.response_timeout_ms
   598→                        ),
   599→                    );
   600→                }
   601→            }
   602→        }
   603→
   604→        // No response file - worker may not support ping
   605→        // This is not an error if the check is disabled or worker is new
   606→        HealthCheckResult::skipped(HealthCheckType::ResponseHealth)
   607→    }
   608→
   609→    /// Check if worker's PID exists and is not a zombie.
   610→    fn check_pid_exists(&self, worker: &WorkerStatusInfo) -> HealthCheckResult {
   611→        let Some(pid) = worker.pid else {
   612→            return HealthCheckResult::failed(
   613→                HealthCheckType::PidExists,
   614→                HealthErrorType::Unknown,
   615→                "No PID recorded in status file",
   616→            );
   617→        };
   618→
   619→        // Check if process exists using kill -0
   620→        let output = Command::new("kill")
   621→            .arg("-0")
   622→            .arg(pid.to_string())
   623→            .output();
   624→
   625→        match output {
   626→            Ok(output) if output.status.success() => {
   627→                // Process exists - check if it's a zombie
   628→                let stat_path = format!("/proc/{}/stat", pid);
   629→                if let Ok(stat) = std::fs::read_to_string(&stat_path) {
   630→                    // Third field is state: Z = zombie
   631→                    let fields: Vec<&str> = stat.split_whitespace().collect();
   632→                    if fields.len() > 2 && fields[2] == "Z" {
   633→                        return HealthCheckResult::failed(
   634→                            HealthCheckType::PidExists,
   635→                            HealthErrorType::DeadProcess,
   636→                            format!("Process {} is a zombie", pid),
   637→                        );
   638→                    }
   639→                }
   640→                HealthCheckResult::passed(HealthCheckType::PidExists)
   641→            }
   642→            _ => {
   643→                HealthCheckResult::failed(
   644→                    HealthCheckType::PidExists,
   645→                    HealthErrorType::DeadProcess,
   646→                    format!("Process {} does not exist", pid),
   647→                )
   648→            }
   649→        }
   650→    }
   651→
   652→    /// Check if worker's last activity is within threshold.
   653→    fn check_activity_fresh(&self, worker: &WorkerStatusInfo) -> HealthCheckResult {
   654→        let Some(last_activity) = worker.last_activity else {
   655→            // No activity recorded - skip if worker is starting
   656→            if worker.status == WorkerStatus::Starting {
   657→                return HealthCheckResult::passed(HealthCheckType::ActivityFresh);
   658→            }
   659→            return HealthCheckResult::failed(
   660→                HealthCheckType::ActivityFresh,
   661→                HealthErrorType::StaleActivity,
   662→                "No activity timestamp recorded",
   663→            );
   664→        };
   665→
   666→        let now = Utc::now();
   667→        let elapsed = now.signed_duration_since(last_activity);
   668→        let elapsed_secs = elapsed.num_seconds();
   669→
   670→        if elapsed_secs > self.config.stale_activity_threshold_secs {
   671→            let elapsed_mins = elapsed_secs / 60;
   672→            return HealthCheckResult::failed(
   673→                HealthCheckType::ActivityFresh,
   674→                HealthErrorType::StaleActivity,
   675→                format!(
   676→                    "No activity for {} minutes (threshold: {} mins)",
   677→                    elapsed_mins,
   678→                    self.config.stale_activity_threshold_secs / 60
   679→                ),
   680→            );
   681→        }
   682→
   683→        HealthCheckResult::passed(HealthCheckType::ActivityFresh)
   684→    }
   685→
   686→    /// Check memory usage (Linux only, uses /proc).
   687→    fn check_memory_usage(&self, worker: &WorkerStatusInfo) -> HealthCheckResult {
   688→        let Some(pid) = worker.pid else {
   689→            return HealthCheckResult::skipped(HealthCheckType::MemoryUsage);
   690→        };
   691→
   692→        if self.config.memory_limit_mb == 0 {
   693→            return HealthCheckResult::skipped(HealthCheckType::MemoryUsage);
   694→        }
   695→
   696→        // Read RSS from /proc/<pid>/status
   697→        let status_path = format!("/proc/{}/status", pid);
   698→        if let Ok(content) = std::fs::read_to_string(&status_path) {
   699→            for line in content.lines() {
   700→                if line.starts_with("VmRSS:") {
   701→                    // Parse "VmRSS: 12345 kB"
   702→                    let parts: Vec<&str> = line.split_whitespace().collect();
   703→                    if parts.len() >= 2 {
   704→                        if let Ok(rss_kb) = parts[1].parse::<u64>() {
   705→                            let rss_mb = rss_kb / 1024;
   706→                            if rss_mb > self.config.memory_limit_mb {
   707→                                return HealthCheckResult::failed(
   708→                                    HealthCheckType::MemoryUsage,
   709→                                    HealthErrorType::HighMemory,
   710→                                    format!(
   711→                                        "Memory usage {}MB exceeds limit {}MB",
   712→                                        rss_mb, self.config.memory_limit_mb
   713→                                    ),
   714→                                );
   715→                            }
   716→                            return HealthCheckResult::passed(HealthCheckType::MemoryUsage);
   717→                        }
   718→                    }
   719→                }
   720→            }
   721→        }
   722→
   723→        // Could not read memory info - skip
   724→        HealthCheckResult::skipped(HealthCheckType::MemoryUsage)
   725→    }
   726→
   727→    /// Check if task has been stuck for too long.
   728→    fn check_task_progress(&self, worker: &WorkerStatusInfo) -> HealthCheckResult {
   729→        // Only check active workers with a task
   730→        if worker.status != WorkerStatus::Active {
   731→            return HealthCheckResult::passed(HealthCheckType::TaskProgress);
   732→        }
   733→
   734→        let Some(last_activity) = worker.last_activity else {
   735→            return HealthCheckResult::passed(HealthCheckType::TaskProgress);
   736→        };
   737→
   738→        let now = Utc::now();
   739→        let elapsed = now.signed_duration_since(last_activity);
   740→        let elapsed_mins = elapsed.num_minutes();
   741→
   742→        // If worker is active with a task but no activity for task_stuck_threshold_mins
   743→        if elapsed_mins > self.config.task_stuck_threshold_mins && worker.current_task.is_some() {
   744→            return HealthCheckResult::failed(
   745→                HealthCheckType::TaskProgress,
   746→                HealthErrorType::StuckTask,
   747→                format!(
   748→                    "Task {} stuck for {} minutes",
   749→                    worker.current_task.as_deref().unwrap_or("unknown"),
   750→                    elapsed_mins
   751→                ),
   752→            );
   753→        }
   754→
   755→        HealthCheckResult::passed(HealthCheckType::TaskProgress)
   756→    }
   757→
   758→    /// Record a recovery attempt for a worker.
   759→    pub fn record_recovery_attempt(&mut self, worker_id: &str) {
   760→        let attempts = self.recovery_attempts.entry(worker_id.to_string()).or_insert(0);
   761→        *attempts = attempts.saturating_add(1);
   762→        info!(
   763→            worker_id = %worker_id,
   764→            attempts = *attempts,
   765→            max = self.config.max_recovery_attempts,
   766→            "Recorded recovery attempt"
   767→        );
   768→    }
   769→
   770→    /// Check if worker has exceeded max recovery attempts.
   771→    pub fn is_recovery_exhausted(&self, worker_id: &str) -> bool {
   772→        self.recovery_attempts
   773→            .get(worker_id)
   774→            .map(|&attempts| attempts >= self.config.max_recovery_attempts)
   775→            .unwrap_or(false)
   776→    }
   777→
   778→    /// Reset recovery attempts for a worker (after successful recovery).
   779→    pub fn reset_recovery_attempts(&mut self, worker_id: &str) {
   780→        self.recovery_attempts.remove(worker_id);
   781→        self.consecutive_failures.remove(worker_id);
   782→        debug!(worker_id = %worker_id, "Reset recovery attempts and consecutive failures");
   783→    }
   784→
   785→    /// Get consecutive failure count for a worker.
   786→    pub fn consecutive_failures(&self, worker_id: &str) -> u8 {
   787→        self.consecutive_failures.get(worker_id).copied().unwrap_or(0)
   788→    }
   789→
   790→    /// Check if auto-restart should be triggered for a worker.
   791→    pub fn should_auto_restart(&self, worker_id: &str) -> bool {
   792→        if !self.config.enable_auto_recovery {
   793→            return false;
   794→        }
   795→        self.consecutive_failures
   796→            .get(worker_id)
   797→            .map(|&failures| failures >= self.config.auto_restart_after_failures)
   798→            .unwrap_or(false)
   799→    }
   800→
   801→    /// Get the configuration.
   802→    pub fn config(&self) -> &HealthMonitorConfig {
   803→        &self.config
   804→    }
   805→
   806→    /// Get the log directory.
   807→    pub fn log_dir(&self) -> &PathBuf {
   808→        &self.log_dir
   809→    }
   810→}
   811→
   812→/// Convenience function to check health of a single worker.
   813→pub fn check_worker_health(
   814→    worker_id: &str,
   815→    status_dir: &PathBuf,
   816→    log_dir: &PathBuf,
   817→) -> forge_core::Result<WorkerHealthStatus> {
   818→    let config = HealthMonitorConfig::default();
   819→    let mut monitor = HealthMonitor::with_dirs(config, status_dir.clone(), log_dir.clone())?;
   820→
   821→    let worker = monitor
   822→        .status_reader
   823→        .read_worker(worker_id)?
   824→        .ok_or_else(|| forge_core::ForgeError::StatusFileParse {
   825→            path: status_dir.join(format!("{}.json", worker_id)),
   826→            message: "Worker not found".to_string(),
