    #[test]
    fn test_health_indicator() {
        let mut status = WorkerHealthStatus::new("test-worker");

        // 100% - green
        status.health_score = 1.0;
        assert_eq!(status.health_indicator(), "●");

        // 80% - green
        status.health_score = 0.8;
        assert_eq!(status.health_indicator(), "●");

