     1→//! Worker health alert system for FORGE.
     2→//!
     3→//! This module provides an alert system that tracks and displays notifications
     4→//! when workers become unresponsive, crash, or exhibit degraded health.
     5→//!
     6→//! ## Alert Types
     7→//!
     8→//! - **Critical**: Worker crashed (process died, PID missing)
     9→//! - **Warning**: Worker degraded (stale activity, stuck task)
    10→//! - **Info**: Recovery events, auto-restart triggered
    11→//!
    12→//! ## Features
    13→//!
    14→//! - Alert badge count in header
    15→//! - Alert summary in Overview panel
    16→//! - Acknowledgment/dismiss system
    17→//! - Auto-clear when worker recovers
    18→//! - Sound notification (future)
    19→
    20→use chrono::{DateTime, Utc};
    21→use std::collections::HashMap;
    22→
    23→/// Alert severity level.
    24→#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
    25→pub enum AlertSeverity {
    26→    /// Informational (recovery, auto-restart)
    27→    Info = 0,
    28→    /// Warning (degraded performance, stale activity)
    29→    Warning = 1,
    30→    /// Critical (crashed, dead process)
    31→    Critical = 2,
    32→}
    33→
    34→impl AlertSeverity {
    35→    /// Get the icon for this severity level.
    36→    pub fn icon(&self) -> &'static str {
    37→        match self {
    38→            AlertSeverity::Info => "ℹ",
    39→            AlertSeverity::Warning => "⚠",
    40→            AlertSeverity::Critical => "✖",
    41→        }
    42→    }
    43→
    44→    /// Check if this severity should trigger a notification.
    45→    pub fn should_notify(&self) -> bool {
    46→        matches!(self, AlertSeverity::Critical | AlertSeverity::Warning)
    47→    }
    48→}
    49→
    50→/// Types of worker health alerts.
    51→#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
    52→pub enum AlertType {
    53→    /// Worker process has died (PID check failed)
    54→    WorkerCrashed,
    55→    /// Worker process is a zombie
    56→    WorkerZombie,
    57→    /// Worker has no activity for too long
    58→    WorkerStale,
    59→    /// Worker task has been stuck for too long
    60→    TaskStuck,
    61→    /// Worker memory usage is too high
    62→    MemoryHigh,
    63→    /// Worker not responding to health checks
    64→    WorkerUnresponsive,
    65→    /// Auto-restart triggered
    66→    AutoRestartTriggered,
    67→    /// Recovery attempts exhausted
    68→    RecoveryExhausted,
    69→    /// Worker recovered (info only)
    70→    WorkerRecovered,
    71→    /// New worker spawned (info only)
    72→    WorkerSpawned,
    73→}
    74→
    75→impl AlertType {
    76→    /// Get the default severity for this alert type.
    77→    pub fn default_severity(&self) -> AlertSeverity {
    78→        match self {
    79→            AlertType::WorkerCrashed
    80→            | AlertType::WorkerZombie
    81→            | AlertType::RecoveryExhausted => AlertSeverity::Critical,
    82→            AlertType::WorkerStale
    83→            | AlertType::TaskStuck
    84→            | AlertType::WorkerUnresponsive
    85→            | AlertType::AutoRestartTriggered => AlertSeverity::Warning,
    86→            AlertType::MemoryHigh => AlertSeverity::Warning,
    87→            AlertType::WorkerRecovered | AlertType::WorkerSpawned => AlertSeverity::Info,
    88→        }
    89→    }
    90→
    91→    /// Get a human-readable title for this alert type.
    92→    pub fn title(&self) -> &'static str {
    93→        match self {
    94→            AlertType::WorkerCrashed => "Worker Crashed",
    95→            AlertType::WorkerZombie => "Worker Zombie Process",
    96→            AlertType::WorkerStale => "Worker Stale Activity",
    97→            AlertType::TaskStuck => "Task Stuck",
    98→            AlertType::MemoryHigh => "Memory Usage High",
    99→            AlertType::WorkerUnresponsive => "Worker Unresponsive",
   100→            AlertType::AutoRestartTriggered => "Auto-Restart Triggered",
   101→            AlertType::RecoveryExhausted => "Recovery Exhausted",
   102→            AlertType::WorkerRecovered => "Worker Recovered",
   103→            AlertType::WorkerSpawned => "Worker Spawned",
   104→        }
   105→    }
   106→
   107→    /// Get the default message for this alert type.
   108→    pub fn default_message(&self) -> &'static str {
   109→        match self {
   110→            AlertType::WorkerCrashed => "Worker process has terminated unexpectedly",
   111→            AlertType::WorkerZombie => "Worker process is in zombie state",
   112→            AlertType::WorkerStale => "No activity detected from worker",
   113→            AlertType::TaskStuck => "Current task has been running too long",
   114→            AlertType::MemoryHigh => "Memory usage exceeds threshold",
   115→            AlertType::WorkerUnresponsive => "Worker not responding to health checks",
   116→            AlertType::AutoRestartTriggered => "Worker will be restarted automatically",
   117→            AlertType::RecoveryExhausted => "Max recovery attempts reached",
   118→            AlertType::WorkerRecovered => "Worker health restored",
   119→            AlertType::WorkerSpawned => "New worker started",
   120→        }
   121→    }
   122→}
   123→
   124→/// A single health alert.
   125→#[derive(Debug, Clone)]
   126→pub struct HealthAlert {
   127→    /// Unique alert identifier
   128→    pub id: u64,
   129→    /// Type of alert
   130→    pub alert_type: AlertType,
   131→    /// Severity level
   132→    pub severity: AlertSeverity,
   133→    /// Worker ID this alert is for
   134→    pub worker_id: String,
   135→    /// Alert title
   136→    pub title: String,
   137→    /// Detailed message
   138→    pub message: String,
   139→    /// When the alert was first raised
   140→    pub created_at: DateTime<Utc>,
   141→    /// When the alert was last updated
   142→    pub updated_at: DateTime<Utc>,
   143→    /// Whether the alert has been acknowledged
   144→    pub acknowledged: bool,
   145→    /// Number of times this alert has occurred
   146→    pub occurrence_count: u32,
   147→    /// Whether this is an active alert (vs historical)
   148→    pub is_active: bool,
   149→}
   150→
   151→impl HealthAlert {
   152→    /// Create a new alert.
   153→    pub fn new(
   154→        id: u64,
   155→        alert_type: AlertType,
   156→        worker_id: impl Into<String>,
   157→    ) -> Self {
   158→        Self {
   159→            id,
   160→            alert_type,
   161→            severity: alert_type.default_severity(),
   162→            worker_id: worker_id.into(),
   163→            title: alert_type.title().to_string(),
   164→            message: alert_type.default_message().to_string(),
   165→            created_at: Utc::now(),
   166→            updated_at: Utc::now(),
   167→            acknowledged: false,
   168→            occurrence_count: 1,
   169→            is_active: true,
   170→        }
   171→    }
   172→
   173→    /// Create with a custom message.
   174→    pub fn with_message(mut self, message: impl Into<String>) -> Self {
   175→        self.message = message.into();
   176→        self
   177→    }
   178→
   179→    /// Create with a custom severity.
   180→    pub fn with_severity(mut self, severity: AlertSeverity) -> Self {
   181→        self.severity = severity;
   182→        self
   183→    }
   184→
   185→    /// Acknowledge this alert.
   186→    pub fn acknowledge(&mut self) {
   187→        self.acknowledged = true;
   188→        self.updated_at = Utc::now();
   189→    }
   190→
   191→    /// Mark this alert as resolved/inactive.
   192→    pub fn resolve(&mut self) {
   193→        self.is_active = false;
   194→        self.updated_at = Utc::now();
   195→    }
   196→
   197→    /// Increment occurrence count (for deduplication).
   198→    pub fn increment_occurrence(&mut self) {
   199→        self.occurrence_count += 1;
   200→        self.updated_at = Utc::now();
   201→    }
   202→
   203→    /// Format for display in one line.
   204→    pub fn format_compact(&self) -> String {
   205→        let ack_marker = if self.acknowledged { "✓" } else { " " };
   206→        let count_marker = if self.occurrence_count > 1 {
   207→            format!(" (x{})", self.occurrence_count)
   208→        } else {
   209→            String::new()
   210→        };
   211→        format!(
   212→            "{} {} [{}] {}{}",
   213→            ack_marker,
   214→            self.severity.icon(),
   215→            self.worker_id,
   216→            self.title,
   217→            count_marker
   218→        )
   219→    }
   220→
   221→    /// Format for detailed display.
   222→    pub fn format_detail(&self) -> String {
   223→        let time = self.created_at.format("%H:%M:%S");
   224→        let ack_status = if self.acknowledged { "acknowledged" } else { "active" };
   225→        let count_info = if self.occurrence_count > 1 {
   226→            format!(" (occurred {} times)", self.occurrence_count)
   227→        } else {
   228→            String::new()
   229→        };
   230→
   231→        format!(
   232→            "[{}] {} {} - {}{}\n  {}",
   233→            time,
   234→            self.severity.icon(),
   235→            self.worker_id,
   236→            self.title,
   237→            count_info,
   238→            self.message
   239→        )
   240→    }
   241→}
