   243→/// Alert manager that tracks and manages health alerts.
   244→#[derive(Debug, Clone)]
   245→pub struct AlertManager {
   246→    /// All alerts by ID
   247→    alerts: HashMap<u64, HealthAlert>,
   248→    /// Active alerts by (worker_id, alert_type) for deduplication
   249→    active_keys: HashMap<(String, AlertType), u64>,
   250→    /// Next alert ID
   251→    next_id: u64,
   252→    /// Maximum active alerts to track
   253→    max_active: usize,
   254→    /// Count of unacknowledged critical alerts
   255→    critical_count: usize,
   256→    /// Count of unacknowledged warning alerts
   257→    warning_count: usize,
   258→}
   259→
   260→impl Default for AlertManager {
   261→    fn default() -> Self {
   262→        Self::new(100)
   263→    }
   264→}
   265→
   266→impl AlertManager {
   267→    /// Create a new alert manager with a maximum number of active alerts.
   268→    pub fn new(max_active: usize) -> Self {
   269→        Self {
   270→            alerts: HashMap::new(),
   271→            active_keys: HashMap::new(),
   272→            next_id: 1,
   273→            max_active,
   274→            critical_count: 0,
   275→            warning_count: 0,
   276→        }
   277→    }
   278→
   279→    /// Raise a new alert or increment occurrence if duplicate.
   280→    pub fn raise(
   281→        &mut self,
   282→        alert_type: AlertType,
   283→        worker_id: impl Into<String>,
   284→        message: Option<String>,
   285→    ) -> u64 {
   286→        let worker_id = worker_id.into();
   287→        let key = (worker_id.clone(), alert_type);
   288→
   289→        // Check for existing active alert
   290→        if let Some(&existing_id) = self.active_keys.get(&key) {
   291→            if let Some(alert) = self.alerts.get_mut(&existing_id) {
   292→                if alert.is_active {
   293→                    alert.increment_occurrence();
   294→                    if let Some(msg) = message {
   295→                        alert.message = msg;
   296→                    }
   297→                    return existing_id;
   298→                }
   299→            }
   300→        }
   301→
   302→        // Create new alert
   303→        let id = self.next_id;
   304→        self.next_id += 1;
   305→
   306→        let mut alert = HealthAlert::new(id, alert_type, worker_id.clone());
   307→        if let Some(msg) = message {
   308→            alert = alert.with_message(msg);
   309→        }
   310→
   311→        // Update counts
   312→        if !alert.acknowledged {
   313→            match alert.severity {
   314→                AlertSeverity::Critical => self.critical_count += 1,
   315→                AlertSeverity::Warning => self.warning_count += 1,
   316→                AlertSeverity::Info => {}
   317→            }
   318→        }
   319→
   320→        // Store alert
   321→        self.alerts.insert(id, alert);
   322→        self.active_keys.insert(key, id);
   323→
   324→        // Prune if needed
   325→        if self.alerts.len() > self.max_active {
   326→            self.prune_oldest_resolved();
   327→        }
   328→
   329→        id
   330→    }
   331→
   332→    /// Acknowledge an alert by ID.
   333→    pub fn acknowledge(&mut self, alert_id: u64) -> bool {
   334→        if let Some(alert) = self.alerts.get_mut(&alert_id) {
   335→            if !alert.acknowledged {
   336→                alert.acknowledge();
   337→                // Update counts
   338→                match alert.severity {
   339→                    AlertSeverity::Critical => self.critical_count = self.critical_count.saturating_sub(1),
   340→                    AlertSeverity::Warning => self.warning_count = self.warning_count.saturating_sub(1),
   341→                    AlertSeverity::Info => {}
   342→                }
   343→            }
   344→            return true;
   345→        }
   346→        false
   347→    }
   348→
   349→    /// Acknowledge all alerts for a worker.
   350→    pub fn acknowledge_all_for_worker(&mut self, worker_id: &str) -> usize {
   351→        let mut count = 0;
   352→        for alert in self.alerts.values_mut() {
   353→            if alert.worker_id == worker_id && !alert.acknowledged && alert.is_active {
   354→                alert.acknowledge();
   355→                count += 1;
   356→                // Update counts
   357→                match alert.severity {
   358→                    AlertSeverity::Critical => self.critical_count = self.critical_count.saturating_sub(1),
   359→                    AlertSeverity::Warning => self.warning_count = self.warning_count.saturating_sub(1),
   360→                    AlertSeverity::Info => {}
   361→                }
   362→            }
   363→        }
   364→        count
   365→    }
   366→
   367→    /// Acknowledge all active alerts.
   368→    pub fn acknowledge_all(&mut self) -> usize {
   369→        let mut count = 0;
   370→        for alert in self.alerts.values_mut() {
   371→            if !alert.acknowledged && alert.is_active {
   372→                alert.acknowledge();
   373→                count += 1;
   374→            }
   375→        }
   376→        self.critical_count = 0;
   377→        self.warning_count = 0;
   378→        count
   379→    }
   380→
   381→    /// Resolve (clear) an alert - called when worker recovers.
   382→    pub fn resolve(&mut self, alert_id: u64) -> bool {
   383→        if let Some(alert) = self.alerts.get_mut(&alert_id) {
   384→            if alert.is_active {
   385→                alert.resolve();
   386→                // Remove from active keys
   387→                let key = (alert.worker_id.clone(), alert.alert_type);
   388→                self.active_keys.remove(&key);
   389→                // Update counts
   390→                if !alert.acknowledged {
   391→                    match alert.severity {
   392→                        AlertSeverity::Critical => self.critical_count = self.critical_count.saturating_sub(1),
   393→                        AlertSeverity::Warning => self.warning_count = self.warning_count.saturating_sub(1),
   394→                        AlertSeverity::Info => {}
   395→                    }
   396→                }
   397→            }
   398→            return true;
   399→        }
   400→        false
   401→    }
   402→
   403→    /// Resolve all alerts for a worker (called on recovery).
   404→    pub fn resolve_all_for_worker(&mut self, worker_id: &str) -> usize {
   405→        let mut count = 0;
   406→        let ids: Vec<u64> = self
   407→            .alerts
   408→            .iter()
   409→            .filter(|(_, a)| a.worker_id == worker_id && a.is_active)
   410→            .map(|(id, _)| *id)
   411→            .collect();
   412→
   413→        for id in ids {
   414→            if self.resolve(id) {
   415→                count += 1;
   416→            }
   417→        }
   418→        count
   419→    }
   420→
   421→    /// Get an alert by ID.
   422→    pub fn get(&self, alert_id: u64) -> Option<&HealthAlert> {
   423→        self.alerts.get(&alert_id)
   424→    }
   425→
   426→    /// Get all active alerts (unacknowledged and acknowledged).
   427→    pub fn active_alerts(&self) -> Vec<&HealthAlert> {
   428→        self.alerts
   429→            .values()
   430→            .filter(|a| a.is_active)
   431→            .collect()
   432→    }
   433→
   434→    /// Get unacknowledged alerts only.
   435→    pub fn unacknowledged_alerts(&self) -> Vec<&HealthAlert> {
   436→        self.alerts
   437→            .values()
   438→            .filter(|a| a.is_active && !a.acknowledged)
   439→            .collect()
   440→    }
   441→
   442→    /// Get alerts sorted by severity (critical first) and then by time.
   443→    pub fn alerts_by_severity(&self) -> Vec<&HealthAlert> {
   444→        let mut alerts: Vec<_> = self.active_alerts();
   445→        alerts.sort_by(|a, b| {
   446→            // Sort by: severity desc, then unacknowledged first, then time desc
   447→            b.severity
   448→                .cmp(&a.severity)
   449→                .then(a.acknowledged.cmp(&b.acknowledged))
   450→                .then(b.created_at.cmp(&a.created_at))
   451→        });
   452→        alerts
   453→    }
   454→
   455→    /// Get count of active alerts.
   456→    pub fn active_count(&self) -> usize {
   457→        self.alerts.values().filter(|a| a.is_active).count()
   458→    }
   459→
   460→    /// Get count of unacknowledged alerts.
   461→    pub fn unacknowledged_count(&self) -> usize {
   462→        self.alerts
   463→            .values()
   464→            .filter(|a| a.is_active && !a.acknowledged)
   465→            .count()
   466→    }
   467→
   468→    /// Get count of critical unacknowledged alerts.
   469→    pub fn critical_count(&self) -> usize {
   470→        self.critical_count
   471→    }
   472→
   473→    /// Get count of warning unacknowledged alerts.
   474→    pub fn warning_count(&self) -> usize {
   475→        self.warning_count
   476→    }
   477→
   478→    /// Check if there are any active alerts.
   479→    pub fn has_alerts(&self) -> bool {
   480→        self.alerts.values().any(|a| a.is_active)
   481→    }
   482→
   483→    /// Check if there are any unacknowledged alerts.
   484→    pub fn has_unacknowledged(&self) -> bool {
   485→        self.critical_count > 0 || self.warning_count > 0
   486→    }
   487→
   488→    /// Get alert summary for badge display.
   489→    pub fn badge_summary(&self) -> AlertBadge {
   490→        AlertBadge {
   491→            critical: self.critical_count,
   492→            warning: self.warning_count,
   493→            total: self.unacknowledged_count(),
   494→        }
   495→    }
   496→
   497→    /// Clear all alerts (for testing/reset).
   498→    pub fn clear(&mut self) {
   499→        self.alerts.clear();
   500→        self.active_keys.clear();
   501→        self.critical_count = 0;
   502→        self.warning_count = 0;
   503→    }
   504→
   505→    /// Prune oldest resolved alerts.
   506→    fn prune_oldest_resolved(&mut self) {
   507→        let mut resolved: Vec<_> = self
   508→            .alerts
   509→            .iter()
   510→            .filter(|(_, a)| !a.is_active)
   511→            .collect();
   512→        resolved.sort_by_key(|(_, a)| a.created_at);
   513→
   514→        let to_remove: Vec<u64> = resolved
   515→            .into_iter()
   516→            .take(self.alerts.len().saturating_sub(self.max_active))
   517→            .map(|(id, _)| *id)
   518→            .collect();
   519→
   520→        for id in to_remove {
   521→            self.alerts.remove(&id);
   522→        }
   523→    }
   524→}
   525→
   526→/// Summary badge for alert display.
   527→#[derive(Debug, Clone, Copy, Default)]
   528→pub struct AlertBadge {
   529→    /// Critical alert count
   530→    pub critical: usize,
   531→    /// Warning alert count
   532→    pub warning: usize,
   533→    /// Total unacknowledged count
   534→    pub total: usize,
   535→}
   536→
   537→impl AlertBadge {
   538→    /// Check if badge should be displayed.
   539→    pub fn should_display(&self) -> bool {
   540→        self.total > 0
   541→    }
   542→
   543→    /// Format for display in header.
