   566→/// Notification manager for alert sounds and visual feedback.
   567→///
   568→/// Handles terminal bell notifications and tracks cooldowns to avoid spam.
   569→#[derive(Debug)]
   570→pub struct AlertNotifier {
   571→    /// Last time a bell was triggered
   572→    last_bell: Option<std::time::Instant>,
   573→    /// Minimum interval between bells (in seconds)
   574→    bell_interval_secs: u64,
   575→    /// Whether bell is enabled for critical alerts
   576→    bell_on_critical: bool,
   577→    /// Whether bell is enabled for warning alerts
   578→    bell_on_warning: bool,
   579→    /// Whether visual flash is enabled
   580→    visual_flash_enabled: bool,
   581→    /// Pending bell to be triggered on next render
   582→    pending_bell: bool,
   583→    /// Pending flash to be triggered on next render
   584→    pending_flash: bool,
   585→    /// Flash start time (for timing the flash duration)
   586→    flash_start: Option<std::time::Instant>,
   587→}
   588→
   589→impl Default for AlertNotifier {
   590→    fn default() -> Self {
   591→        Self {
   592→            last_bell: None,
   593→            bell_interval_secs: 30,
   594→            bell_on_critical: true,
   595→            bell_on_warning: false,
   596→            visual_flash_enabled: true,
   597→            pending_bell: false,
   598→            pending_flash: false,
   599→            flash_start: None,
   600→        }
   601→    }
   602→}
   603→
   604→impl AlertNotifier {
   605→    /// Create a new alert notifier with default settings.
   606→    pub fn new() -> Self {
   607→        Self::default()
   608→    }
   609→
   610→    /// Configure the notifier from settings.
   611→    pub fn configure(
   612→        &mut self,
   613→        bell_on_critical: bool,
   614→        bell_on_warning: bool,
   615→        bell_interval_secs: u64,
   616→        visual_flash_enabled: bool,
   617→    ) {
   618→        self.bell_on_critical = bell_on_critical;
   619→        self.bell_on_warning = bell_on_warning;
   620→        self.bell_interval_secs = bell_interval_secs;
   621→        self.visual_flash_enabled = visual_flash_enabled;
   622→    }
   623→
   624→    /// Notify about a new alert (queues bell/flash if applicable).
   625→    pub fn notify(&mut self, severity: AlertSeverity) {
   626→        let should_bell = match severity {
   627→            AlertSeverity::Critical => self.bell_on_critical,
   628→            AlertSeverity::Warning => self.bell_on_warning,
   629→            AlertSeverity::Info => false,
   630→        };
   631→
   632→        if should_bell && self.can_ring_bell() {
   633→            self.pending_bell = true;
   634→        }
   635→
   636→        if self.visual_flash_enabled && severity == AlertSeverity::Critical {
   637→            self.pending_flash = true;
   638→            self.flash_start = Some(std::time::Instant::now());
   639→        }
   640→    }
   641→
   642→    /// Check if enough time has passed to ring the bell again.
   643→    fn can_ring_bell(&self) -> bool {
   644→        match self.last_bell {
   645→            None => true,
   646→            Some(last) => {
   647→                last.elapsed().as_secs() >= self.bell_interval_secs
   648→            }
   649→        }
   650→    }
   651→
   652→    /// Take and clear the pending bell flag, returning whether to ring the bell.
   653→    ///
   654→    /// Call this during the render loop to trigger the bell.
   655→    pub fn take_pending_bell(&mut self) -> bool {
   656→        if self.pending_bell {
   657→            self.pending_bell = false;
   658→            self.last_bell = Some(std::time::Instant::now());
   659→            true
   660→        } else {
   661→            false
   662→        }
   663→    }
   664→
   665→    /// Check if visual flash is currently active (within 200ms of alert).
   666→    pub fn is_flashing(&self) -> bool {
   667→        if let Some(start) = self.flash_start {
   668→            start.elapsed().as_millis() < 200
   669→        } else {
   670→            false
   671→        }
   672→    }
   673→
   674→    /// Clear the flash state after it has been displayed.
   675→    pub fn clear_flash(&mut self) {
   676→        self.pending_flash = false;
   677→        // Keep flash_start for timing
   678→    }
   679→
   680→    /// Ring the terminal bell (BEL character).
   681→    ///
   682→    /// This outputs the ASCII BEL character (0x07) which causes most terminals
   683→    /// to emit an audible beep or visual bell depending on terminal settings.
   684→    pub fn ring_bell() {
   685→        // Output BEL character (ASCII 7) to trigger terminal bell
   686→        print!("\x07");
   687→        // Flush to ensure it's sent immediately
   688→        use std::io::Write;
   689→        let _ = std::io::stdout().flush();
   690→    }
   691→}
