        ];

        for (keycode, expected_view) in view_keys {
            let event =
                handler.handle_key(crossterm::event::KeyEvent::new(keycode, KeyModifiers::NONE));
            assert_eq!(
                event,
                AppEvent::SwitchView(expected_view),
                "Key {:?} should switch to {:?}",
                keycode,
                expected_view
            );
