        // Verify lowercase 'o' is now spawn Opus, not Overview
        let event = handler.handle_key(crossterm::event::KeyEvent::new(
            KeyCode::Char('o'),
            KeyModifiers::NONE,
        ));
        assert_eq!(
            event,
