            KeyCode::Up,
            KeyModifiers::NONE,
        ));
        assert_eq!(up, AppEvent::NavigateUp);

        let down = handler.handle_key(crossterm::event::KeyEvent::new(
            KeyCode::Down,
            KeyModifiers::NONE,
